CREATE TEMP TABLE pulse_domain1_payload (data jsonb) ON COMMIT DROP;
INSERT INTO pulse_domain1_payload VALUES ($domain1_v2${"schemaVersion":1,"contentVersion":"domain1.v2-current-schema","sourceSha256":"ebe2591c8091f4a9277e678f2e4930aac2091ef4ff757e897edda28694fe84f9","courses":[{"code":"M1-F","tier":1,"title":"Tìm kiếm và lưu trữ thông tin cơ bản","description":"Tìm đúng nguồn, kiểm tra dấu hiệu tin cậy và lưu lại tài liệu để người khác truy xuất được.","purpose":"Bậc 1–2 · 6 giờ","modules":[{"title":"Tìm kiếm thông tin bằng từ khóa","description":"Nêu nhu cầu thông tin, chọn từ khóa và tìm đến nguồn gốc.","purpose":{"title":"Lập nhật ký tìm và truy nguồn","goal":"Từ một yêu cầu mơ hồ, tạo truy vấn có phạm vi và dẫn được người khác tới nguồn gốc.","example":"Yêu cầu “tìm số liệu tháng 9” chưa đủ để tìm. Viết lại thành “số đơn hàng trực tuyến của chiến dịch CAMP07 trong 01–30/09/2026 để so với báo cáo bán hàng”. Truy vấn đầu “đơn hàng CAMP07” còn rộng; truy vấn sau thêm kỳ và hệ thống nguồn. Nhật ký ghi cả hai truy vấn, đường dẫn báo cáo gốc, người xuất và thời điểm truy cập. Nếu chỉ thấy ảnh chụp, ghi trạng thái “chưa xác minh”, không tự tạo số.","steps":["Viết câu hỏi công việc gồm đối tượng, chỉ tiêu, kỳ và mục đích.","Tìm tối đa ba lượt; ghi từ khóa ở mỗi lượt và vì sao đổi từ khóa.","Mở tài liệu gốc, ghi đơn vị tạo dữ liệu, ngày/kỳ và URL hoặc mã hồ sơ.","Nêu một kết quả bị loại và lý do; bàn giao nhật ký để người khác lặp lại."],"output":"Nhật ký một trang: câu hỏi, tối đa ba lượt tìm, nguồn chọn, nguồn loại và giới hạn còn chưa xác minh.","checks":["Truy vấn thứ hai khác có chủ đích so với truy vấn đầu.","Nguồn được chọn là nguồn gốc hoặc ghi rõ không tìm được nguồn gốc.","Người nhận có thể tìm lại tài liệu mà không hỏi người lập."],"mistake":"Chọn kết quả đầu tiên hoặc ảnh chụp vì nhìn có vẻ đúng mà không giữ dấu vết nguồn.","minutes":40,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":45,"slides":[{"code":"M1-F/M01/S01","title":"Biết mình cần tìm gì","content":"Trước khi mở trình tìm kiếm, ghi rõ câu hỏi công việc, phạm vi, thời điểm cần số liệu và người sẽ dùng kết quả. Câu “cần thông tin thị trường” quá rộng; “số đơn hàng tháng 9 của kênh trực tuyến” có thể kiểm tra được.\n\n### Từ nhu cầu đến truy vấn\n- 01 · Câu hỏi · Cần thông tin gì?\n- 02 · Phạm vi · Đối tượng · kỳ · đơn vị\n- 03 · Nguồn · Đường dẫn gốc\nBa ô nối tiếp mô tả cách chuyển một yêu cầu công việc thành truy vấn có thể lặp lại.\n\n### Tự kiểm tra\nViết một câu nhu cầu thông tin có phạm vi và kỳ thời gian.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S02","title":"Từ khóa thay cho câu hỏi dài","content":"Công cụ tìm kiếm tra trong chỉ mục trang đã thu thập, không quét toàn bộ Internet ngay khi bạn gõ. Chọn 2–4 từ mang nghĩa chính: đối tượng, chỉ tiêu và thời điểm. Đọc tiêu đề, địa chỉ và mô tả của kết quả trước khi mở. Nhãn “Được tài trợ” nói về vị trí quảng cáo, không bảo đảm nội dung chính xác. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Hai truy vấn cùng một nhu cầu\n- Rộng · doanh thu · Quá nhiều kết quả\n- Rõ hơn · doanh thu trực tuyến 09/2026 · Có phạm vi và kỳ\nMinh họa truy vấn mơ hồ và truy vấn được thu hẹp bằng đối tượng, chỉ tiêu, thời gian.\n\n### Tự kiểm tra\nGhi hai truy vấn: truy vấn đầu và truy vấn đã tinh chỉnh.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S03","title":"Đến tài liệu gốc","content":"Đối chiếu trang tóm tắt với tài liệu do đơn vị tạo ra thông tin công bố. Ghi đường dẫn, tác giả hoặc đơn vị và ngày truy cập. Nếu không thấy tài liệu gốc, hãy ghi rõ giới hạn thay vì tự đoán.\n\n### Dấu vết nguồn\n- Kết quả tìm · Trang tóm tắt\n- Tài liệu gốc · Đơn vị tạo dữ liệu\n- Nhật ký · URL · ngày truy cập\nSơ đồ lần ngược từ kết quả tìm kiếm về tài liệu gốc và nhật ký nguồn.\n\n### Tự kiểm tra\nLưu nguồn gốc cùng nhật ký tìm kiếm.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S04","title":"Biến lời nhờ mơ hồ thành câu hỏi tìm","content":"Khi ai đó yêu cầu “tìm số liệu mới nhất”, hãy hỏi số liệu nào, cho đơn vị nào, kỳ nào và dùng để làm gì. Câu trả lời quyết định từ khóa cũng như nguồn có thẩm quyền. Nếu thiếu một trong các yếu tố này, hãy ghi giả định trước khi tìm.\n\n### Hai yêu cầu\n- Mơ hồ · Tìm doanh thu mới nhất\n- Có thể làm · Doanh thu online · 09/2026 · chi nhánh A\nSo sánh lời nhờ mơ hồ với câu hỏi công việc có phạm vi kiểm tra được.\n\n### Tự kiểm tra\nViết lại yêu cầu thành một câu có đối tượng, chỉ tiêu và kỳ.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S05","title":"Tạo nhóm từ khóa rồi tinh chỉnh","content":"Bắt đầu với danh từ chỉ đối tượng và chỉ tiêu, sau đó thêm thời gian hoặc mã nội bộ. Nếu kết quả quá rộng, thu hẹp phạm vi; nếu không có kết quả, thử tên đồng nghĩa hoặc bỏ bớt điều kiện. Lưu cả truy vấn đầu và truy vấn đã sửa để người khác lặp lại.\n\n### Vòng tinh chỉnh\n- 1 · Tìm rộng · Chủ đề chính\n- 2 · Đọc kết quả · Xem lệch ở đâu\n- 3 · Tinh chỉnh · Thêm kỳ · mã · nguồn\nBa bước phản hồi cho thấy truy vấn được điều chỉnh dựa trên kết quả, không tìm tùy tiện.\n\n### Tự kiểm tra\nNêu lý do đổi một từ khóa trong truy vấn.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S06","title":"Không chọn nguồn vì đứng đầu danh sách","content":"Dòng kết quả tìm kiếm chỉ cho biết tiêu đề, địa chỉ và đoạn trích. Mở tài liệu để kiểm tra người công bố, kỳ số liệu và phương pháp. Kết quả quảng cáo hoặc bản sao có thể hữu ích để định hướng, nhưng không trở thành nguồn gốc chỉ vì xuất hiện trước.\n\n### Một kết quả cần kiểm tra\n- Tiêu đề · Báo cáo tháng 9\n- Địa chỉ · Nơi đăng chưa rõ\n- Cần mở · Tác giả · kỳ · tài liệu gốc\nThẻ kết quả tìm kiếm minh họa thông tin hiện ra và thông tin phải kiểm tra tiếp.\n\n### Tự kiểm tra\nChỉ ra ba dữ kiện cần xem sau khi mở kết quả.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S07","title":"Tìm đúng hồ sơ của công việc mình","content":"Áp dụng cách tìm vào bộ dữ liệu của vị trí đang học. Ghi rõ mã, kỳ và nơi giữ tài liệu gốc; nếu chỉ có bản chụp hoặc bản chưa duyệt, hãy đánh dấu cần xác minh. Cùng một kỹ năng tìm kiếm sẽ cho câu hỏi và nguồn khác nhau ở Kế toán và Marketing. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nNêu nguồn đầu tiên sẽ mở và lý do.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S08","title":"Nộp nhật ký tìm ngắn gọn","content":"Trước khi sang mô đun sau, hãy lưu câu hỏi ban đầu, hai truy vấn, nguồn cuối cùng và một nguồn đã loại cùng lý do. Một đồng nghiệp phải có thể lặp lại đường tìm mà không hỏi lại bạn. Đây là bước chuẩn bị trực tiếp cho bài cuối khóa.\n\n### Sản phẩm của mô đun\n- 01 · Câu hỏi · Nêu phạm vi\n- 02 · Nhật ký · Hai truy vấn\n- 03 · Nguồn · URL · lý do chọn\nBa thành phần của nhật ký tìm là câu hỏi, truy vấn và nguồn được chọn có lý do.\n\n### Tự kiểm tra\nKiểm tra xem người khác có mở lại nguồn gốc từ nhật ký không.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S09","title":"Làm mẫu · Lập nhật ký tìm và truy nguồn","content":"Yêu cầu “tìm số liệu tháng 9” chưa đủ để tìm. Viết lại thành “số đơn hàng trực tuyến của chiến dịch CAMP07 trong 01–30/09/2026 để so với báo cáo bán hàng”. Truy vấn đầu “đơn hàng CAMP07” còn rộng; truy vấn sau thêm kỳ và hệ thống nguồn. Nhật ký ghi cả hai truy vấn, đường dẫn báo cáo gốc, người xuất và thời điểm truy cập. Nếu chỉ thấy ảnh chụp, ghi trạng thái “chưa xác minh”, không tự tạo số. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S10","title":"Tự làm · Lập nhật ký tìm và truy nguồn","content":"Từ một yêu cầu mơ hồ, tạo truy vấn có phạm vi và dẫn được người khác tới nguồn gốc. Thực hiện theo bốn bước: 1) Viết câu hỏi công việc gồm đối tượng, chỉ tiêu, kỳ và mục đích. 2) Tìm tối đa ba lượt; ghi từ khóa ở mỗi lượt và vì sao đổi từ khóa. 3) Mở tài liệu gốc, ghi đơn vị tạo dữ liệu, ngày/kỳ và URL hoặc mã hồ sơ. 4) Nêu một kết quả bị loại và lý do; bàn giao nhật ký để người khác lặp lại. Sản phẩm cần tạo: Nhật ký một trang: câu hỏi, tối đa ba lượt tìm, nguồn chọn, nguồn loại và giới hạn còn chưa xác minh.\n\n### Bốn bước thực hành\n- 01 · Viết câu hỏi công việc gồm đối tượng, chỉ tiêu, kỳ và mục đích.\n- 02 · Tìm tối đa ba lượt; ghi từ khóa ở mỗi lượt và vì sao đổi từ khóa.\n- 03 · Mở tài liệu gốc, ghi đơn vị tạo dữ liệu, ngày/kỳ và URL hoặc mã hồ sơ.\n- 04 · Nêu một kết quả bị loại và lý do; bàn giao nhật ký để người khác lặp lại.\nQuy trình thực hành lập nhật ký tìm và truy nguồn có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-F/M01/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Truy vấn thứ hai khác có chủ đích so với truy vấn đầu. Nguồn được chọn là nguồn gốc hoặc ghi rõ không tìm được nguồn gốc. Người nhận có thể tìm lại tài liệu mà không hỏi người lập. Lỗi thường gặp: Chọn kết quả đầu tiên hoặc ảnh chụp vì nhìn có vẻ đúng mà không giữ dấu vết nguồn. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Truy vấn thứ hai khác có chủ đích so với truy vấn đầu.\n- Tiêu chí 2 · Nguồn được chọn là nguồn gốc hoặc ghi rõ không tìm được nguồn gốc.\n- Tiêu chí 3 · Người nhận có thể tìm lại tài liệu mà không hỏi người lập.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"}],"questions":[{"code":"M1-F/M01/GENERAL/Q01","text":"Cách tìm nào có thể kiểm tra lại?","explanation":"Truy vấn và nguồn gốc cần được ghi để người khác lặp lại việc tìm.","options":["Gõ câu hỏi rất dài rồi chọn kết quả đầu","Ghi nhu cầu, dùng từ khóa chính và lưu đường dẫn nguồn","Chỉ đọc kết quả có nhãn quảng cáo"],"correctIndex":1},{"code":"M1-F/M01/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-F/M01/GENERAL/Q03","text":"Yêu cầu nào đủ rõ để bắt đầu tìm?","explanation":"Cần có đối tượng, chỉ tiêu, kỳ và mục đích sử dụng.","options":["Tìm mọi thứ về khách hàng","Tìm số đơn hàng kênh trực tuyến của tháng 9/2026 để đối chiếu báo cáo","Tìm kết quả mới nhất trên mạng"],"correctIndex":1},{"code":"M1-F/M01/GENERAL/Q04","text":"Một kết quả được tài trợ xuất hiện đầu danh sách. Bạn làm gì?","explanation":"Vị trí quảng cáo không chứng minh nội dung đúng hoặc sai.","options":["Dùng ngay vì đứng đầu","Bỏ hết kết quả được tài trợ","Mở và kiểm tra tác giả, nguồn gốc, kỳ dữ liệu như các kết quả khác"],"correctIndex":2},{"code":"M1-F/M01/GENERAL/Q05","text":"Nhật ký tìm kiếm nào giúp đồng nghiệp lặp lại?","explanation":"Nhật ký phải giữ đường tìm và căn cứ chọn nguồn.","options":["Chỉ ghi kết luận","Ghi câu hỏi, hai truy vấn đã thử, URL nguồn và lý do chọn","Chụp màn hình trang kết quả"],"correctIndex":1}]},{"title":"Nhận biết nguồn đáng tin cậy","description":"Nhận diện tác giả, thời điểm, mục đích và bằng chứng trước khi dùng thông tin.","purpose":{"title":"Chấm độ phù hợp của ba nguồn","goal":"Xếp hạng năm nguồn theo nguồn gốc, kỳ dữ liệu, mục đích và khả năng kiểm chứng trước khi dùng.","example":"Có ba lựa chọn: báo cáo gốc đã duyệt của đúng kỳ; bài tóm tắt trích báo cáo đó; ảnh chụp bảng không ghi người xuất. Báo cáo gốc là nguồn chính. Bài tóm tắt hữu ích để định hướng nhưng không phải xác nhận độc lập. Ảnh chụp chỉ là dấu hiệu cần kiểm tra. Kết luận phải nêu báo cáo gốc phù hợp cho câu hỏi nào và điểm còn thiếu, ví dụ phương pháp chọn mẫu.","steps":["Chọn năm kết quả cùng chủ đề; lập bảng tác giả/đơn vị tạo, ngày xuất, kỳ dữ liệu, phương pháp và mục đích.","Vẽ mũi tên từ bài tóm tắt và ảnh chụp về nguồn được trích, nếu có.","Xếp hạng năm nguồn; ghi nguồn nào chỉ dùng để định hướng và vì sao.","Viết hai câu kết luận: phạm vi sử dụng được và giới hạn cần xác minh."],"output":"Bảng xếp hạng năm nguồn, mỗi nguồn có một câu giải thích và quyết định dùng/chưa dùng.","checks":["Không đếm hai trang cùng trích một báo cáo là hai nguồn độc lập.","Phân biệt ngày đăng bài với kỳ số liệu.","Không dùng nhãn “đáng tin tuyệt đối” khi phương pháp chưa rõ."],"mistake":"Coi nhiều đường link là nhiều xác nhận dù tất cả lấy từ một bảng gốc.","minutes":40,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":45,"slides":[{"code":"M1-F/M02/S01","title":"Ai đứng sau thông tin?","content":"Xem tên tổ chức, tác giả, tài liệu gốc và cách liên hệ. Tên miền chỉ là tín hiệu để xác định nơi xuất bản, không phải bằng chứng tự động rằng số liệu đúng.\n\n### Hồ sơ một nguồn\n- Tác giả · Ai tạo ra số liệu?\n- Kỳ dữ liệu · Tháng nào, năm nào?\n- Mục đích · Báo cáo hay quảng cáo?\nPhiếu kiểm nguồn gồm tác giả, kỳ dữ liệu và mục đích công bố.\n\n### Tự kiểm tra\nGhi người tạo dữ liệu và người đăng lại.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S02","title":"Thông tin có còn phù hợp?","content":"Kiểm tra ngày công bố, kỳ dữ liệu, phương pháp và mục đích của bài viết. Một nguồn đáng tin ở chủ đề này có thể không phù hợp với câu hỏi khác. Bài không ghi nguồn hoặc chỉ giật tít cần được kiểm chứng thêm. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Mới chưa chắc phù hợp\n- Nguồn A · Xuất hôm nay · Dữ liệu năm trước\n- Nguồn B · Xuất tuần trước · Dữ liệu đúng kỳ cần\nHai nguồn được so theo ngày xuất và kỳ dữ liệu, cho thấy ngày xuất mới không tự bảo đảm phù hợp.\n\n### Tự kiểm tra\nSo thời điểm của nguồn với thời điểm quyết định.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S03","title":"Hai trang chưa chắc là hai nguồn","content":"Nếu hai trang cùng trích một báo cáo, chúng không tạo thành hai bằng chứng độc lập. Mở liên kết về báo cáo gốc và ghi điểm trùng hoặc khác nhau trước khi kết luận.\n\n### Hai trang, một nguồn gốc\n- Trang A · Trích báo cáo X\n- Trang B · Trích báo cáo X\n- Nguồn gốc · Báo cáo X\nHai trang dẫn cùng báo cáo X được gom về một nguồn gốc thay vì đếm thành hai bằng chứng độc lập.\n\n### Tự kiểm tra\nNêu một điểm còn chưa xác minh được.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S04","title":"Tách người đăng khỏi người tạo dữ liệu","content":"Một bài tổng hợp có thể dẫn nguồn đáng tin nhưng vẫn diễn giải sai. Hãy lần về báo cáo do đơn vị tạo dữ liệu công bố, xem bảng và phần phương pháp. Ghi rõ đâu là dữ liệu, đâu là nhận định của tác giả và đâu là suy luận của mình.\n\n### Chuỗi truyền thông tin\n- Đơn vị tạo · Bảng gốc\n- Người đăng · Bài tóm tắt\n- Người học · Kết luận có dẫn nguồn\nBa lớp thể hiện số liệu có thể bị diễn giải qua từng lần đăng lại.\n\n### Tự kiểm tra\nPhân loại một câu trong tài liệu thành số liệu hay nhận định.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S05","title":"So ngày công bố với kỳ dữ liệu","content":"Bài xuất hôm nay có thể dùng số liệu từ năm trước. Mỗi nguồn cần hai mốc: ngày tài liệu được công bố hoặc cập nhật và kỳ mà số liệu thực sự phản ánh. Quyết định cần số hiện tại thì nguồn quá cũ phải ghi rõ hạn chế, dù tổ chức xuất bản rất uy tín.\n\n### Hai mốc khác nhau\n- 09/2025 · Kỳ dữ liệu\n- 10/2026 · Ngày xuất bài\nTrục thời gian cho thấy bài mới xuất nhưng dữ liệu bên trong cũ hơn một năm.\n\n### Tự kiểm tra\nĐánh dấu nguồn đúng kỳ và nguồn cần bổ sung.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S06","title":"Hai đường link có thể cùng một bằng chứng","content":"Trước khi nói đã kiểm tra chéo, xem hai trang lấy số từ đâu. Nếu cả hai trích báo cáo X, số nguồn độc lập là một. Muốn kiểm chứng mạnh hơn, tìm nguồn có cách thu thập riêng hoặc kiểm tra trực tiếp sổ/hệ thống gốc.\n\n### Nguồn lặp không tăng độ chắc\n- Bài A · Dẫn X\n- Bài B · Dẫn X\n- Báo cáo X · Một nguồn gốc\nHai bài A/B quy về cùng báo cáo X; sơ đồ không đếm thành hai xác nhận độc lập.\n\n### Tự kiểm tra\nVẽ mũi tên từ từng trang tới nơi tạo số liệu.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S07","title":"Chấm độ tin cậy trước khi dùng","content":"Trong hồ sơ của vị trí, hãy so bản gốc, bản sao và bản chưa duyệt. Nguồn phù hợp phải đúng đối tượng, kỳ và trạng thái. Một ảnh chụp có thể giúp nhận ra vấn đề nhưng không thay thế tệp gốc có lịch sử/phiên bản. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nChọn một nguồn chính và ghi một điều còn nghi vấn.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S08","title":"Viết nhận xét nguồn không tuyệt đối hóa","content":"Ghi kết luận theo cấu trúc: nguồn này đủ dùng cho câu hỏi nào, vì sao và giới hạn ở đâu. Tránh gắn nhãn “đáng tin hoàn toàn” hoặc “sai hoàn toàn” nếu chưa kiểm tra phương pháp. Minh bạch giới hạn là một phần của năng lực đánh giá nguồn.\n\n### Ba phần nhận xét\n- Phù hợp · Đúng câu hỏi · kỳ\n- Căn cứ · Có gốc · phương pháp\n- Giới hạn · Điều chưa xác minh\nKhung nhận xét nguồn có phần dùng được, lý do và giới hạn chưa kiểm tra.\n\n### Tự kiểm tra\nViết hai câu đánh giá một nguồn, có điều kiện sử dụng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S09","title":"Làm mẫu · Chấm độ phù hợp của ba nguồn","content":"Có ba lựa chọn: báo cáo gốc đã duyệt của đúng kỳ; bài tóm tắt trích báo cáo đó; ảnh chụp bảng không ghi người xuất. Báo cáo gốc là nguồn chính. Bài tóm tắt hữu ích để định hướng nhưng không phải xác nhận độc lập. Ảnh chụp chỉ là dấu hiệu cần kiểm tra. Kết luận phải nêu báo cáo gốc phù hợp cho câu hỏi nào và điểm còn thiếu, ví dụ phương pháp chọn mẫu. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S10","title":"Tự làm · Chấm độ phù hợp của ba nguồn","content":"Xếp hạng năm nguồn theo nguồn gốc, kỳ dữ liệu, mục đích và khả năng kiểm chứng trước khi dùng. Thực hiện theo bốn bước: 1) Chọn năm kết quả cùng chủ đề; lập bảng tác giả/đơn vị tạo, ngày xuất, kỳ dữ liệu, phương pháp và mục đích. 2) Vẽ mũi tên từ bài tóm tắt và ảnh chụp về nguồn được trích, nếu có. 3) Xếp hạng năm nguồn; ghi nguồn nào chỉ dùng để định hướng và vì sao. 4) Viết hai câu kết luận: phạm vi sử dụng được và giới hạn cần xác minh. Sản phẩm cần tạo: Bảng xếp hạng năm nguồn, mỗi nguồn có một câu giải thích và quyết định dùng/chưa dùng.\n\n### Bốn bước thực hành\n- 01 · Chọn năm kết quả cùng chủ đề; lập bảng tác giả/đơn vị tạo, ngày xuất, kỳ dữ liệu, phương pháp và mục đích.\n- 02 · Vẽ mũi tên từ bài tóm tắt và ảnh chụp về nguồn được trích, nếu có.\n- 03 · Xếp hạng năm nguồn; ghi nguồn nào chỉ dùng để định hướng và vì sao.\n- 04 · Viết hai câu kết luận: phạm vi sử dụng được và giới hạn cần xác minh.\nQuy trình thực hành chấm độ phù hợp của ba nguồn có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-F/M02/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Không đếm hai trang cùng trích một báo cáo là hai nguồn độc lập. Phân biệt ngày đăng bài với kỳ số liệu. Không dùng nhãn “đáng tin tuyệt đối” khi phương pháp chưa rõ. Lỗi thường gặp: Coi nhiều đường link là nhiều xác nhận dù tất cả lấy từ một bảng gốc. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Không đếm hai trang cùng trích một báo cáo là hai nguồn độc lập.\n- Tiêu chí 2 · Phân biệt ngày đăng bài với kỳ số liệu.\n- Tiêu chí 3 · Không dùng nhãn “đáng tin tuyệt đối” khi phương pháp chưa rõ.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"}],"questions":[{"code":"M1-F/M02/GENERAL/Q01","text":"Khi hai bài cùng ghi một con số, bạn nên làm gì?","explanation":"Các trang cùng chép một báo cáo chỉ là một nguồn gốc dữ liệu.","options":["Coi đó là hai xác nhận độc lập","Chọn bài có nhiều lượt xem hơn","Kiểm tra xem cả hai có cùng dẫn về một nguồn gốc không"],"correctIndex":2},{"code":"M1-F/M02/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-F/M02/GENERAL/Q03","text":"Bài viết đăng hôm nay nhưng số liệu thuộc năm trước. Nhận xét nào đúng?","explanation":"Ngày xuất bài và kỳ mà dữ liệu phản ánh là hai mốc khác nhau.","options":["Luôn phù hợp vì mới đăng","Cần đối chiếu kỳ dữ liệu với kỳ của quyết định","Chỉ cần xem lượt chia sẻ"],"correctIndex":1},{"code":"M1-F/M02/GENERAL/Q04","text":"Bài A và B đều trích báo cáo X. Có bao nhiêu nguồn gốc độc lập?","explanation":"Hai đường dẫn cùng quy về báo cáo X không tạo hai bằng chứng độc lập.","options":["Một","Hai","Ba"],"correctIndex":0},{"code":"M1-F/M02/GENERAL/Q05","text":"Nhận xét nào về một nguồn là minh bạch nhất?","explanation":"Đánh giá nguồn phải nói rõ phạm vi dùng được và giới hạn chưa xác minh.","options":["Nguồn này chắc chắn đúng mọi trường hợp","Nguồn này dùng được cho kỳ tháng 9, nhưng chưa rõ cách chọn mẫu","Nguồn này có biểu đồ đẹp"],"correctIndex":1}]},{"title":"Lưu trữ và sắp xếp tài liệu","description":"Lưu tệp có tên, phiên bản và vị trí có thể tìm lại.","purpose":{"title":"Thiết kế thư mục bàn giao có phiên bản","goal":"Tổ chức bản gốc, bản làm việc và bản đã duyệt để truy xuất, phân quyền và đối chiếu.","example":"Một bộ chứng từ mẫu gồm PDF gốc, bảng đối chiếu và bản xuất để đọc. Đặt tên theo kỳ–mã–chủ đề–phiên bản, ví dụ 2026-09_CP017_chung-tu_v01.pdf; không dùng “final_moi_nhat”. Giữ bản gốc ở thư mục chỉ đọc. Bản làm việc có phiên bản và người sửa; bản đã duyệt có ngày duyệt. Người kiểm tra chỉ cần quyền xem bản phù hợp.","steps":["Phân loại tệp: bản gốc, bản làm việc, bản đã duyệt.","Viết quy ước tên gồm kỳ, mã/chủ đề, phiên bản và phần mở rộng.","Vẽ cấu trúc thư mục và gán quyền xem/sửa cho từng vai trò.","Mô phỏng đổi v01 thành v02 và ghi nguyên nhân thay đổi."],"output":"Ảnh hoặc sơ đồ thư mục chứa ba tệp đặt tên theo quy ước, bảng quyền và một dòng nhật ký phiên bản.","checks":["Bản gốc không bị ghi đè.","Tên tệp tự thể hiện được kỳ và phiên bản.","Người chỉ cần đọc không có quyền chỉnh sửa toàn bộ thư mục."],"mistake":"Dùng tên “bản cuối” cho nhiều tệp và cấp quyền sửa cho bất kỳ ai có liên kết.","minutes":40,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":45,"slides":[{"code":"M1-F/M03/S01","title":"Chọn tệp đúng việc","content":"Bảng tính phù hợp khi cần tính và lọc; PDF phù hợp khi cần chia sẻ bố cục cố định. Luôn giữ tệp gốc và ghi nơi lấy. Đừng biến ảnh chụp thành “dữ liệu gốc” nếu vẫn còn bảng nguồn.\n\n### Tệp để xử lý và tệp để đọc\n- Bảng tính · Lọc · tính · kiểm tra\n- PDF · Đọc bản đã chốt\nHai thẻ minh họa chọn định dạng theo mục đích xử lý tiếp hay chia sẻ bản cố định.\n\n### Tự kiểm tra\nChọn định dạng phù hợp với việc xử lý tiếp theo.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S02","title":"Tên tệp mô tả được nội dung","content":"Dùng quy ước ổn định như năm-tháng-ngày_chủ-đề_phiên-bản. Đặt các thành phần ở cùng vị trí trong mọi tên tệp để sắp xếp và tìm lại. Tránh các tên “final2_moi_nhat”. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Quy ước tên tệp\n- Kỳ · 2026-09\n- Chủ đề · chung-tu_CP017\n- Phiên bản · v01.pdf\nTên tệp được ghép từ kỳ, chủ đề và phiên bản để sắp xếp, tra cứu.\n\n### Tự kiểm tra\nĐề xuất một tên tệp và thư mục dễ tra cứu.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S03","title":"Giữ phiên bản và đường dẫn","content":"Sổ ghi nguồn nên có tên, đường dẫn, người phụ trách, kỳ dữ liệu và phiên bản. Tài liệu nhạy cảm chỉ chia sẻ với người cần dùng. Khi sửa, tạo phiên bản mới hoặc ghi lịch sử thay đổi thay vì ghi đè không dấu vết.\n\n### Chuỗi bàn giao\n- Nguồn gốc · Tệp gốc\n- Bản làm việc · Có phiên bản\n- Người nhận · Đúng quyền\nSơ đồ lưu bản gốc, tạo bản làm việc có phiên bản và chia sẻ đúng quyền.\n\n### Tự kiểm tra\nKiểm tra người nhận có quyền phù hợp.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S04","title":"Sắp theo một quy tắc mà cả nhóm hiểu","content":"Chọn một trục chính như kỳ công việc hoặc dự án; bên dưới mới tách nguồn, bản làm việc và bản duyệt. Nếu một tệp hợp với hai thư mục, hãy dùng sổ đăng ký hoặc liên kết thay vì tạo hai bản không đồng bộ. Tên thư mục cần ngắn nhưng đủ phân biệt.\n\n### Thư mục mẫu\n- 2026-09 · Kỳ\n- 01_Nguồn · Tệp gốc\n- 02_Làm-việc · Bản đang sửa\n- 03_Duyệt · Bản chốt\nCây thư mục minh họa một kỳ và ba trạng thái tài liệu thay vì nhiều bản rải rác.\n\n### Tự kiểm tra\nVẽ cây ba tầng cho ca học của bạn.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S05","title":"Đừng dùng tên “final_final”","content":"Phiên bản nên tăng có quy tắc: v01 là bản đầu, v02 là bản sửa; ngày hoặc kỳ đứng đầu giúp sắp xếp. Giữ ghi chú ngắn về thay đổi quan trọng. Nếu tài liệu được duyệt lại, trạng thái duyệt là trường riêng, không chỉ suy từ tên tệp.\n\n### Hai bản có dấu vết\n- v01 · Bản nhận\n- v02 · Sửa số liệu\n- Duyệt · Có trạng thái riêng\nTrục phiên bản phân biệt số phiên bản với trạng thái phê duyệt.\n\n### Tự kiểm tra\nĐặt tên cho bản gốc và bản sửa của cùng tài liệu.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S06","title":"Chia sẻ theo nhiệm vụ","content":"Trước khi gửi liên kết, hỏi người nhận cần xem hay sửa, trong bao lâu và có dữ liệu cá nhân không. Chia sẻ tệp đã duyệt để đọc nếu chỉ cần tham khảo; giữ thư mục nguồn và bản làm việc cho người có trách nhiệm. Không đưa tệp nhạy cảm vào kho công khai.\n\n### Quyền tương ứng việc\n- Người kiểm tra · Xem bản chốt\n- Người soạn · Sửa bản làm việc\n- Công khai · Không chứa dữ liệu nhạy cảm\nBa ví dụ gắn quyền với nhu cầu, theo nguyên tắc quyền tối thiểu.\n\n### Tự kiểm tra\nChỉ định quyền xem/sửa cho hai người nhận khác nhau.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S07","title":"Bàn giao một bộ hồ sơ tìm được","content":"Tạo sổ ghi tên, mã, kỳ, nguồn và phiên bản cho các tệp trong ca học. Kiểm tra bản nào đã duyệt và bản nào chỉ là tài liệu tham khảo. Với Kế toán, giữ dấu vết chứng từ–bút toán; với Marketing, giữ mã chiến dịch–brief–báo cáo. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nNêu khóa tra cứu giúp đồng nghiệp tìm đúng bản.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S08","title":"Thử tìm lại bằng mắt của đồng nghiệp","content":"Giả sử bạn rời nhóm một tuần: người khác có biết tài liệu nằm đâu, bản nào được dùng và ai được hỏi khi số liệu sai không? Nếu câu trả lời là không, hãy sửa tên, sổ đăng ký hoặc quyền trước khi nộp. Khả năng tìm lại là tiêu chí thực tế của việc quản lý thông tin.\n\n### Kiểm thử truy xuất\n- 01 · Có mã · Tìm trong sổ\n- 02 · Có đường dẫn · Mở đúng bản\n- 03 · Có chủ sở hữu · Hỏi khi cần\nBa bước kiểm thử cho thấy một người khác có thể tìm và kiểm tra tài liệu.\n\n### Tự kiểm tra\nTự tìm lại một tệp chỉ bằng mã và kỳ.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S09","title":"Làm mẫu · Thiết kế thư mục bàn giao có phiên bản","content":"Một bộ chứng từ mẫu gồm PDF gốc, bảng đối chiếu và bản xuất để đọc. Đặt tên theo kỳ–mã–chủ đề–phiên bản, ví dụ 2026-09_CP017_chung-tu_v01.pdf; không dùng “final_moi_nhat”. Giữ bản gốc ở thư mục chỉ đọc. Bản làm việc có phiên bản và người sửa; bản đã duyệt có ngày duyệt. Người kiểm tra chỉ cần quyền xem bản phù hợp. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S10","title":"Tự làm · Thiết kế thư mục bàn giao có phiên bản","content":"Tổ chức bản gốc, bản làm việc và bản đã duyệt để truy xuất, phân quyền và đối chiếu. Thực hiện theo bốn bước: 1) Phân loại tệp: bản gốc, bản làm việc, bản đã duyệt. 2) Viết quy ước tên gồm kỳ, mã/chủ đề, phiên bản và phần mở rộng. 3) Vẽ cấu trúc thư mục và gán quyền xem/sửa cho từng vai trò. 4) Mô phỏng đổi v01 thành v02 và ghi nguyên nhân thay đổi. Sản phẩm cần tạo: Ảnh hoặc sơ đồ thư mục chứa ba tệp đặt tên theo quy ước, bảng quyền và một dòng nhật ký phiên bản.\n\n### Bốn bước thực hành\n- 01 · Phân loại tệp: bản gốc, bản làm việc, bản đã duyệt.\n- 02 · Viết quy ước tên gồm kỳ, mã/chủ đề, phiên bản và phần mở rộng.\n- 03 · Vẽ cấu trúc thư mục và gán quyền xem/sửa cho từng vai trò.\n- 04 · Mô phỏng đổi v01 thành v02 và ghi nguyên nhân thay đổi.\nQuy trình thực hành thiết kế thư mục bàn giao có phiên bản có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"},{"code":"M1-F/M03/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Bản gốc không bị ghi đè. Tên tệp tự thể hiện được kỳ và phiên bản. Người chỉ cần đọc không có quyền chỉnh sửa toàn bộ thư mục. Lỗi thường gặp: Dùng tên “bản cuối” cho nhiều tệp và cấp quyền sửa cho bất kỳ ai có liên kết. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Bản gốc không bị ghi đè.\n- Tiêu chí 2 · Tên tệp tự thể hiện được kỳ và phiên bản.\n- Tiêu chí 3 · Người chỉ cần đọc không có quyền chỉnh sửa toàn bộ thư mục.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nNational Archives · Quy ước đặt tên tệp\nhttps://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html"}],"questions":[{"code":"M1-F/M03/GENERAL/Q01","text":"Tên tệp nào dễ truy xuất và sắp xếp theo thời gian?","explanation":"Tên nhất quán với kỳ, chủ đề và phiên bản dễ tìm lại hơn.","options":["bao_cao_final_moi.xlsx","2026-09_bao-cao-kpi_v01.xlsx","document1.xlsx"],"correctIndex":1},{"code":"M1-F/M03/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-F/M03/GENERAL/Q03","text":"Bạn cần lưu một bản gốc và một bản để chỉnh sửa. Cách nào phù hợp?","explanation":"Bản gốc cần giữ dấu vết; bản làm việc cần phiên bản rõ.","options":["Ghi đè bản gốc sau mỗi lần sửa","Giữ bản gốc, tạo bản làm việc có phiên bản và quyền phù hợp","Chỉ gửi cả hai qua chat"],"correctIndex":1},{"code":"M1-F/M03/GENERAL/Q04","text":"Đồng nghiệp chỉ cần đọc tài liệu đã chốt. Quyền nào là đủ?","explanation":"Cấp quyền tối thiểu theo nhu cầu công việc.","options":["Xem bản đã duyệt","Sửa tất cả tệp nguồn","Quản trị kho dữ liệu"],"correctIndex":0},{"code":"M1-F/M03/GENERAL/Q05","text":"Tên tệp “final_moi_nhat2.xlsx” gây khó khăn chính gì?","explanation":"Tên tệp có kỳ, chủ đề và phiên bản giúp tìm, sắp xếp và bàn giao.","options":["Không thể mở bằng máy tính","Không thể nhận ra kỳ, nội dung và phiên bản một cách nhất quán","Tệp luôn quá lớn"],"correctIndex":1}]}],"assignments":{"general":{"title":"Bài cuối khóa M1-F · vị trí của bạn","situation":"Áp dụng vào một quyết định thực tế của vị trí.","prompt":"Nêu nhu cầu, nguồn, cách kiểm tra, sản phẩm công việc và kết luận có giới hạn.","deliverables":["Nhật ký nguồn và định nghĩa","Sản phẩm công việc có thể kiểm tra","Giới hạn và đề xuất tiếp theo"],"caseFacts":[],"rubric":[["Từ khóa hợp lý, không chép nguyên câu hỏi",20],["3 nguồn có đánh giá độ tin cậy",25],["Tệp lưu đúng thư mục và tên quy ước",20],["5 ý tóm tắt có nguồn cho từng ý",20],["Trình bày rõ, đúng hạn",15]],"pass":70,"minimumCriterion":null,"requirements":["Nêu nhu cầu và từ khóa; tìm 3 nguồn, ghi tác giả hoặc đơn vị, kỳ và lý do tin cậy của từng nguồn.","Lưu ít nhất 1 tệp vào thư mục có tên và phiên bản; nộp ảnh hoặc sơ đồ thư mục.","Viết 5 ý tóm tắt, mỗi ý ghi nguồn; bản tổng hợp tối đa 1 trang, kèm minh chứng thư mục."]},"accounting":{"title":"Bài cuối khóa M1-F · Kế toán","situation":"Quản lý cần bộ chứng từ chi phí tháng 9 để kiểm tra một khoản đã ghi sổ.","prompt":"Tìm ba chứng từ chi phí của một kỳ giả lập; ghi truy vấn, đánh giá nguồn, lập bảng mã chứng từ–bút toán và quy ước tên tệp.","deliverables":["Nhật ký tìm và ba đường dẫn/mã nguồn","Bảng đối chiếu chứng từ–bút toán","Thư mục/tên tệp có kỳ và phiên bản"],"caseFacts":["CP017 · 04/09/2026 · hóa đơn PDF lưu kho chứng từ: 12.000.000 đ · đã duyệt","BT017 · 05/09/2026 · bút toán sổ cái: 12.000.000 đ · tham chiếu CP017","Ảnh chuyển tiếp qua chat ghi CP017: 21.000.000 đ · không có chữ ký/phiên bản","CP018 · 12/09/2026 · hóa đơn PDF: 8.500.000 đ · chưa có mã bút toán"],"rubric":[["Từ khóa hợp lý, không chép nguyên câu hỏi",20],["3 nguồn có đánh giá độ tin cậy",25],["Tệp lưu đúng thư mục và tên quy ước",20],["5 ý tóm tắt có nguồn cho từng ý",20],["Trình bày rõ, đúng hạn",15]],"pass":70,"minimumCriterion":null,"requirements":["Nêu nhu cầu và từ khóa; tìm 3 nguồn, ghi tác giả hoặc đơn vị, kỳ và lý do tin cậy của từng nguồn.","Lưu ít nhất 1 tệp vào thư mục có tên và phiên bản; nộp ảnh hoặc sơ đồ thư mục.","Viết 5 ý tóm tắt, mỗi ý ghi nguồn; bản tổng hợp tối đa 1 trang, kèm minh chứng thư mục."]},"marketing":{"title":"Bài cuối khóa M1-F · Marketing","situation":"Nhóm cần tìm bản định hướng chiến dịch và số lượt truy cập của tháng 9.","prompt":"Tìm brief và ba nguồn số liệu cho một chiến dịch giả lập; mô tả nguồn, kỳ và lưu bộ tài liệu có phiên bản.","deliverables":["Nhật ký tìm và đường dẫn nguồn","Bảng ba nguồn kèm đánh giá tin cậy","Thư mục chiến dịch có quy ước tên"],"caseFacts":["CAMP07 · brief v02 · duyệt 01/09/2026; brief v03 đang chờ duyệt","GA4 · báo cáo nguồn truy cập · kỳ 01–30/09/2026 · xuất 02/10/2026","Nền tảng quảng cáo · báo cáo lượt nhấp · cùng kỳ · xuất 01/10/2026","Ảnh chụp dashboard · không ghi ngày xuất hoặc người tạo"],"rubric":[["Từ khóa hợp lý, không chép nguyên câu hỏi",20],["3 nguồn có đánh giá độ tin cậy",25],["Tệp lưu đúng thư mục và tên quy ước",20],["5 ý tóm tắt có nguồn cho từng ý",20],["Trình bày rõ, đúng hạn",15]],"pass":70,"minimumCriterion":null,"requirements":["Nêu nhu cầu và từ khóa; tìm 3 nguồn, ghi tác giả hoặc đơn vị, kỳ và lý do tin cậy của từng nguồn.","Lưu ít nhất 1 tệp vào thư mục có tên và phiên bản; nộp ảnh hoặc sơ đồ thư mục.","Viết 5 ý tóm tắt, mỗi ý ghi nguồn; bản tổng hợp tối đa 1 trang, kèm minh chứng thư mục."]},"hr":{"title":"Bài cuối khóa M1-F · Nhân sự","situation":"Cần tìm phiên bản chính sách nghỉ phép đã duyệt cho nhân viên mới.","prompt":"Tìm và lưu ba chính sách nhân sự giả lập có phiên bản, ngày hiệu lực và nguồn.","deliverables":["Nhật ký nguồn","Bảng đánh giá hiệu lực","Cấu trúc thư mục có quyền phù hợp"],"caseFacts":["Chính sách nghỉ phép v03 · hiệu lực 01/09/2026 · đã ban hành trên cổng nhân sự","Bản v02 · hiệu lực 01/01/2025 · còn nằm trong thư mục chia sẻ cũ","Ảnh chụp trao đổi trong chat không ghi mã văn bản hoặc ngày hiệu lực","Hồ sơ nhân viên mới NV024 cần hướng dẫn về quyền nghỉ phép hiện hành"],"rubric":[["Từ khóa hợp lý, không chép nguyên câu hỏi",20],["3 nguồn có đánh giá độ tin cậy",25],["Tệp lưu đúng thư mục và tên quy ước",20],["5 ý tóm tắt có nguồn cho từng ý",20],["Trình bày rõ, đúng hạn",15]],"pass":70,"minimumCriterion":null,"requirements":["Nêu nhu cầu và từ khóa; tìm 3 nguồn, ghi tác giả hoặc đơn vị, kỳ và lý do tin cậy của từng nguồn.","Lưu ít nhất 1 tệp vào thư mục có tên và phiên bản; nộp ảnh hoặc sơ đồ thư mục.","Viết 5 ý tóm tắt, mỗi ý ghi nguồn; bản tổng hợp tối đa 1 trang, kèm minh chứng thư mục."]},"sales":{"title":"Bài cuối khóa M1-F · Sales/CRM","situation":"Nhân viên cần tìm hồ sơ khách hàng và bảng giá đã được duyệt.","prompt":"Tìm và sắp xếp bộ hồ sơ khách hàng giả lập cùng báo giá đã duyệt.","deliverables":["Nguồn và mã khách hàng","Đánh giá phiên bản báo giá","Thư mục/hồ sơ có ngày"],"caseFacts":["CRM · KH102 · nhu cầu gói dịch vụ A · cập nhật 03/09/2026","Bảng giá v02 · hiệu lực tháng 09/2026 · đã duyệt · 10.000.000 đ","Bảng giá v03 · 9.500.000 đ · đang chờ duyệt","Ảnh báo giá cũ gửi qua chat không ghi mã khách hàng hoặc phiên bản"],"rubric":[["Từ khóa hợp lý, không chép nguyên câu hỏi",20],["3 nguồn có đánh giá độ tin cậy",25],["Tệp lưu đúng thư mục và tên quy ước",20],["5 ý tóm tắt có nguồn cho từng ý",20],["Trình bày rõ, đúng hạn",15]],"pass":70,"minimumCriterion":null,"requirements":["Nêu nhu cầu và từ khóa; tìm 3 nguồn, ghi tác giả hoặc đơn vị, kỳ và lý do tin cậy của từng nguồn.","Lưu ít nhất 1 tệp vào thư mục có tên và phiên bản; nộp ảnh hoặc sơ đồ thư mục.","Viết 5 ý tóm tắt, mỗi ý ghi nguồn; bản tổng hợp tối đa 1 trang, kèm minh chứng thư mục."]},"ceo":{"title":"Bài cuối khóa M1-F · CEO","situation":"CEO cần một nguồn ngành và một báo cáo nội bộ để chuẩn bị cuộc họp.","prompt":"Chuẩn bị bộ nguồn giả lập cho một quyết định trong cuộc họp.","deliverables":["Câu hỏi quyết định","Nguồn nội bộ và ngoài","Bảng tóm tắt có phiên bản"],"caseFacts":["Báo cáo ngành công bố 10/2026 nhưng dùng số liệu thị trường năm 2025","Báo cáo bán hàng nội bộ kỳ 01–09/2026 có nguồn hệ thống CRM","Một slide họp ghi “thị trường tăng mạnh” nhưng không dẫn bảng gốc","Cuộc họp cần quyết định có mở nghiên cứu thị trường quý 4/2026"],"rubric":[["Từ khóa hợp lý, không chép nguyên câu hỏi",20],["3 nguồn có đánh giá độ tin cậy",25],["Tệp lưu đúng thư mục và tên quy ước",20],["5 ý tóm tắt có nguồn cho từng ý",20],["Trình bày rõ, đúng hạn",15]],"pass":70,"minimumCriterion":null,"requirements":["Nêu nhu cầu và từ khóa; tìm 3 nguồn, ghi tác giả hoặc đơn vị, kỳ và lý do tin cậy của từng nguồn.","Lưu ít nhất 1 tệp vào thư mục có tên và phiên bản; nộp ảnh hoặc sơ đồ thư mục.","Viết 5 ý tóm tắt, mỗi ý ghi nguồn; bản tổng hợp tối đa 1 trang, kèm minh chứng thư mục."]}}},{"code":"M1-I","tier":2,"title":"Chiến lược tìm kiếm và quản lý thông tin","description":"Thiết kế chiến lược tìm, so sánh nguồn khác định nghĩa và tổ chức hồ sơ thông tin cho nhóm.","purpose":"Bậc 3–4 · 7,5 giờ","modules":[{"title":"Chiến lược tìm kiếm và toán tử","description":"Biến yêu cầu mơ hồ thành kế hoạch tìm có phạm vi và nhật ký.","purpose":{"title":"Lập chiến lược tìm kiếm phục vụ quyết định","goal":"Xác định câu hỏi, nguồn ưu tiên, truy vấn và điều kiện dừng trước khi tìm sâu.","example":"Để so hiệu quả một chiến dịch theo tháng, không tìm “chiến dịch tốt không”. Hãy xác định quyết định cần hỗ trợ, kỳ, phạm vi, chỉ số và nơi tạo số liệu. Truy vấn có thể dùng cụm từ trong ngoặc kép, site: để giới hạn miền, filetype: để tìm PDF, dấu trừ để loại từ và OR viết hoa để thử hai thuật ngữ tương đương; sau đó vẫn phải mở tài liệu để xác nhận định nghĩa và kỳ. Dừng khi có đủ nguồn cho từng chỉ số hoặc ghi khoảng trống rõ ràng.","steps":["Ghi một quyết định và hai chỉ số có thể làm đổi quyết định.","Lập ma trận từ khóa và ghi ít nhất năm lần tinh chỉnh truy vấn; dùng toán tử phù hợp, giải thích tác dụng.","Xếp thứ tự nguồn nội bộ/chính thức/thứ cấp; ghi lý do.","Lập tiêu chí dừng và nhật ký kết quả tìm/không tìm được."],"output":"Kế hoạch tìm có ma trận từ khóa, ít nhất năm bước tinh chỉnh, nguồn và điều kiện dừng.","checks":["Toán tử tìm kiếm được dùng để lọc, không được coi là xác nhận tính đúng.","Mỗi chỉ số có định nghĩa và kỳ cần tìm.","Khoảng trống nguồn được ghi lại thay vì tự điền số."],"mistake":"Thu thật nhiều kết quả mà không biết kết quả nào phục vụ quyết định.","minutes":55,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":55,"slides":[{"code":"M1-I/M01/S01","title":"Đặt câu hỏi trước khi tìm","content":"Chốt đối tượng, chỉ tiêu, kỳ, địa bàn, mức chi tiết và sản phẩm cần nộp. Tạo ma trận từ khóa gồm thuật ngữ chính, từ đồng nghĩa và từ cần loại trừ. Ghi cả điều kiện dừng tìm khi đã đủ bằng chứng.\n\n### Kế hoạch tìm có điều kiện dừng\n- 01 · Câu hỏi · Đối tượng · kỳ · phạm vi\n- 02 · Từ khóa · Chính · đồng nghĩa\n- 03 · Dừng · Đủ nguồn cho quyết định\nBa giai đoạn tạo kế hoạch tìm trước khi mở công cụ.\n\n### Tự kiểm tra\nViết nhu cầu thông tin theo sáu yếu tố.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S02","title":"Dùng toán tử có chủ đích","content":"Dấu ngoặc kép tìm cụm từ chính xác; site: giới hạn miền; filetype: lọc định dạng; dấu trừ loại chủ đề không liên quan; OR viết hoa tìm một trong hai thuật ngữ. Toán tử giúp lọc kết quả nhưng không tự xác nhận độ tin cậy của tài liệu. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Các toán tử có chức năng khác nhau\n- \"…\" · Khóa cụm từ\n- site: · Giới hạn website/miền\n- filetype: · Giới hạn định dạng\nBa dòng ví dụ phân biệt lọc cụm từ, miền và định dạng trong truy vấn.\n\n### Tự kiểm tra\nLập hai truy vấn khác nhau cho cùng nhu cầu.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S03","title":"Cho người khác lặp lại việc tìm","content":"Ghi truy vấn, công cụ, thời điểm, số kết quả đáng xem và lý do đổi truy vấn. Chỉ giữ các nguồn trả lời đúng phạm vi và kỳ; đánh dấu phần chưa tìm được thay vì kéo dài tìm kiếm vô hạn.\n\n### Nhật ký truy vấn\n- 09:00 · Truy vấn rộng · Ít liên quan\n- 09:10 · Thêm kỳ và site: · Đúng phạm vi\n- 09:20 · Lưu nguồn · Có URL\nTrục thời gian cho thấy truy vấn được chỉnh và lý do dừng tìm.\n\n### Tự kiểm tra\nChọn một quy tắc dừng tìm có lý do.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S04","title":"Tìm bằng các nhóm thuật ngữ","content":"Lập bảng gồm khái niệm chính, từ đồng nghĩa, tên hệ thống, kỳ và điều cần loại trừ. Ví dụ “doanh thu” có thể là doanh thu gộp hoặc thuần; “truy cập” có thể là nhấp hay phiên. Từ khóa phải phản ánh định nghĩa bạn đang cần, không chỉ một từ nghe quen.\n\n### Ma trận truy vấn\n- Khái niệm · Doanh thu / phiên\n- Đồng nghĩa · Tên cũ / tên mới\n- Giới hạn · 09/2026 · nguồn chính\nPhiếu ma trận chứa ba nhóm từ giúp truy vấn vừa đủ rộng vừa đúng phạm vi.\n\n### Tự kiểm tra\nGhi hai từ đồng nghĩa và một từ cần loại.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S05","title":"Dùng cú pháp để thu hẹp, không để xác thực","content":"Dấu ngoặc kép giữ nguyên cụm từ; site: thu hẹp trang hoặc miền; filetype: tìm định dạng. Kết hợp toán tử khi có lý do rõ, rồi mở từng kết quả để kiểm tra nguồn. Một PDF trên website uy tín vẫn có thể chứa số liệu không đúng kỳ hoặc không đúng câu hỏi.\n\n### Truy vấn minh họa\n- Cụm · \"báo cáo quý 3\"\n- Miền · site:gov.vn\n- Dạng · filetype:pdf\nBa thành phần hợp thành truy vấn; hình không khẳng định kết quả tìm được là đúng.\n\n### Tự kiểm tra\nViết một truy vấn và nói từng toán tử làm gì.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S06","title":"Lưu cả kết quả không được chọn","content":"Nhật ký tối thiểu có truy vấn, thời điểm, nguồn mở, lý do chọn hoặc loại và khoảng trống còn lại. Người khác cần hiểu vì sao báo cáo A được dùng thay B. Nếu tài liệu gốc không mở được, ghi trạng thái đó thay vì tự điền nội dung từ đoạn trích.\n\n### Ba lần thử có lý do\n- Lần 1 · Rộng · nhiễu\n- Lần 2 · Thêm kỳ\n- Lần 3 · Nguồn gốc phù hợp\nTrục nhật ký thể hiện mỗi lần đổi truy vấn đều có lý do và kết quả.\n\n### Tự kiểm tra\nViết một dòng nhật ký cho nguồn đã loại.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S07","title":"Lập kế hoạch tìm phục vụ quyết định","content":"Trong ca của vị trí, ghi quyết định cần hỗ trợ rồi tìm ít nhất hai hệ thống nguồn có định nghĩa rõ. Kế toán có thể cần sổ cái và hóa đơn; Marketing cần GA4 và nền tảng quảng cáo. Không trộn các chỉ tiêu khác đơn vị đếm vào một tổng. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nGhi một câu hỏi quyết định và hai nguồn cần truy.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S08","title":"Biết khi nào ngừng tìm","content":"Dừng khi đã có nguồn gốc đáp ứng đúng phạm vi, đủ căn cứ để trả lời và đã ghi giới hạn còn lại. Không dừng chỉ vì có con số đầu tiên; cũng không tìm vô hạn để loại mọi bất định. Nêu rõ điều gì sẽ khiến phải mở lại việc tìm kiếm.\n\n### Quy tắc dừng\n- Đủ · Nguồn · kỳ · định nghĩa rõ\n- Còn thiếu · Ghi khoảng trống\n- Mở lại · Khi giả định đổi\nBa ô quyết định cho biết khi nào kết thúc hoặc lặp lại quá trình tìm.\n\n### Tự kiểm tra\nViết điều kiện dừng và một điều kiện mở lại.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S09","title":"Làm mẫu · Lập chiến lược tìm kiếm phục vụ quyết định","content":"Để so hiệu quả một chiến dịch theo tháng, không tìm “chiến dịch tốt không”. Hãy xác định quyết định cần hỗ trợ, kỳ, phạm vi, chỉ số và nơi tạo số liệu. Truy vấn có thể dùng cụm từ trong ngoặc kép, site: để giới hạn miền, filetype: để tìm PDF, dấu trừ để loại từ và OR viết hoa để thử hai thuật ngữ tương đương; sau đó vẫn phải mở tài liệu để xác nhận định nghĩa và kỳ. Dừng khi có đủ nguồn cho từng chỉ số hoặc ghi khoảng trống rõ ràng. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S10","title":"Tự làm · Lập chiến lược tìm kiếm phục vụ quyết định","content":"Xác định câu hỏi, nguồn ưu tiên, truy vấn và điều kiện dừng trước khi tìm sâu. Thực hiện theo bốn bước: 1) Ghi một quyết định và hai chỉ số có thể làm đổi quyết định. 2) Lập ma trận từ khóa và ghi ít nhất năm lần tinh chỉnh truy vấn; dùng toán tử phù hợp, giải thích tác dụng. 3) Xếp thứ tự nguồn nội bộ/chính thức/thứ cấp; ghi lý do. 4) Lập tiêu chí dừng và nhật ký kết quả tìm/không tìm được. Sản phẩm cần tạo: Kế hoạch tìm có ma trận từ khóa, ít nhất năm bước tinh chỉnh, nguồn và điều kiện dừng.\n\n### Bốn bước thực hành\n- 01 · Ghi một quyết định và hai chỉ số có thể làm đổi quyết định.\n- 02 · Lập ma trận từ khóa và ghi ít nhất năm lần tinh chỉnh truy vấn; dùng toán tử phù hợp, giải thích tác dụng.\n- 03 · Xếp thứ tự nguồn nội bộ/chính thức/thứ cấp; ghi lý do.\n- 04 · Lập tiêu chí dừng và nhật ký kết quả tìm/không tìm được.\nQuy trình thực hành lập chiến lược tìm kiếm phục vụ quyết định có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"},{"code":"M1-I/M01/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Toán tử tìm kiếm được dùng để lọc, không được coi là xác nhận tính đúng. Mỗi chỉ số có định nghĩa và kỳ cần tìm. Khoảng trống nguồn được ghi lại thay vì tự điền số. Lỗi thường gặp: Thu thật nhiều kết quả mà không biết kết quả nào phục vụ quyết định. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Toán tử tìm kiếm được dùng để lọc, không được coi là xác nhận tính đúng.\n- Tiêu chí 2 · Mỗi chỉ số có định nghĩa và kỳ cần tìm.\n- Tiêu chí 3 · Khoảng trống nguồn được ghi lại thay vì tự điền số.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nGoogle · Cách tinh chỉnh kết quả tìm kiếm\nhttps://support.google.com/websearch/answer/2466433?hl=en"}],"questions":[{"code":"M1-I/M01/GENERAL/Q01","text":"Truy vấn nào giới hạn nguồn và định dạng?","explanation":"site: và filetype: phải gắn liền với giá trị; dấu ngoặc kép khóa cụm từ.","options":["\"báo cáo thị trường\" site:gov.vn filetype:pdf","báo cáo thị trường mới nhất đúng nhất","filetype pdf site gov vn báo cáo"],"correctIndex":0},{"code":"M1-I/M01/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-I/M01/GENERAL/Q03","text":"Toán tử site: giúp việc gì?","explanation":"site: là bộ lọc phạm vi tìm, không phải phép xác thực.","options":["Xác nhận mọi tài liệu trên trang đều đúng","Giới hạn kết quả theo website hoặc miền","Tìm tệp PDF ở mọi nơi"],"correctIndex":1},{"code":"M1-I/M01/GENERAL/Q04","text":"Truy vấn đầu cho quá nhiều kết quả. Bước tiếp theo hợp lý?","explanation":"Tinh chỉnh truy vấn có căn cứ và giữ nhật ký để lặp lại.","options":["Bỏ câu hỏi công việc","Thêm kỳ, đối tượng hoặc từ đồng nghĩa rồi ghi lại thay đổi","Chỉ chọn kết quả đầu"],"correctIndex":1},{"code":"M1-I/M01/GENERAL/Q05","text":"Khi nào nên dừng tìm?","explanation":"Điều kiện dừng gắn với nhu cầu quyết định, không với số lượng kết quả tùy ý.","options":["Ngay sau kết quả đầu tiên","Khi đã có nguồn đủ phù hợp cho quyết định và ghi rõ phần còn thiếu","Chỉ khi toàn bộ Internet được xem"],"correctIndex":1}]},{"title":"Đánh giá và so sánh nguồn tin","description":"So tác giả, kỳ, định nghĩa, mục đích và nguồn gốc trước khi chọn chỉ số.","purpose":{"title":"Lập bảng so hai báo cáo không đồng nhất","goal":"Giải thích chênh lệch bằng định nghĩa, phạm vi, kỳ và trạng thái trước khi khuyến nghị.","example":"Báo cáo A là doanh thu đã ghi nhận, báo cáo B là hóa đơn đã xuất. Hai tổng có thể lệch vì hóa đơn hủy hoặc thời điểm ghi nhận. Tương tự, lượt nhấp quảng cáo, phiên GA4 và người dùng mới là ba đơn vị đếm khác nhau; không lấy trung bình hay trừ trực tiếp để gọi là “sai lệch”. Bảng so phải có cột đơn vị đếm, kỳ, bộ lọc, trạng thái và nguồn gốc.","steps":["Chọn ba nguồn cùng chủ đề; ghi số, đơn vị đếm và loại nguồn sơ cấp/thứ cấp.","So tác giả, thời điểm, mục đích, bằng chứng, khả năng kiểm chứng, định nghĩa và kỳ.","Truy một bản ghi/hóa đơn/chiến dịch mẫu để xác minh nguyên nhân chênh lệch.","Viết khuyến nghị có điều kiện và một bước đối soát tiếp."],"output":"Ma trận ba nguồn theo năm tiêu chí, bảng giải thích chênh lệch và brief quyết định một trang.","checks":["Không so trực tiếp các chỉ số khác phạm vi.","Mỗi nguyên nhân chênh lệch có bằng chứng hoặc được ghi là giả định.","Kết luận cho biết số nào dùng được cho câu hỏi nào."],"mistake":"Lấy trung bình hai tổng khi một số gồm giao dịch hủy còn số kia không.","minutes":55,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":55,"slides":[{"code":"M1-I/M02/S01","title":"Phân biệt sơ cấp và thứ cấp","content":"Nguồn sơ cấp là nơi dữ liệu được tạo ra; nguồn thứ cấp diễn giải hoặc trích lại. Nhiều bài cùng dẫn một báo cáo không phải nhiều xác nhận độc lập. Lưu đường dẫn tới tài liệu gốc và mô tả cách thu thập.\n\n### Dòng gốc của chỉ số\n- Bản gốc · Hệ thống tạo dữ liệu\n- Báo cáo · Tổng hợp từ bản gốc\n- Bài viết · Diễn giải lại\nSơ đồ phân biệt dữ liệu sơ cấp, báo cáo tổng hợp và bài diễn giải.\n\n### Tự kiểm tra\nChỉ ra nguồn gốc của một chỉ số.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S02","title":"Hai số khác nhau vì sao?","content":"Trước khi tính trung bình hay chọn số lớn hơn, so định nghĩa chỉ tiêu, mẫu số, kỳ, phạm vi, đơn vị và cách lọc. Các số có thể đều đúng trong phạm vi riêng nhưng không cộng hoặc so trực tiếp được. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Cùng tên, khác cách đo\n- Báo cáo A · Tháng 9 · doanh thu gộp\n- Báo cáo B · Tháng 9 · doanh thu thuần\nHai cột doanh thu có cùng kỳ nhưng định nghĩa khác nên chưa so trực tiếp.\n\n### Tự kiểm tra\nLập bảng so sánh hai con số mâu thuẫn.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S03","title":"Nêu con số kèm giới hạn","content":"Chọn số phù hợp quyết định cần đưa ra và giải thích nguồn, cách đo, độ mới, độ tin cậy. Nếu chưa thể hòa giải, báo cáo khoảng ước lượng hoặc hai cách hiểu; ghi việc phải kiểm tra tiếp.\n\n### Kết luận có giới hạn\n- Dùng được · Định nghĩa khớp quyết định\n- Chưa dùng · Chưa rõ kỳ hoặc phạm vi\n- Việc tiếp · Xác minh nguồn gốc\nBa trạng thái cho quyết định dùng, tạm giữ hoặc kiểm tra thêm một chỉ số.\n\n### Tự kiểm tra\nViết kết luận hai câu có điều kiện sử dụng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S04","title":"So những thuộc tính tạo ra khác biệt","content":"Lập mỗi hàng là một nguồn; các cột gồm người tạo, kỳ, phạm vi, đơn vị, phương pháp và tình trạng duyệt. Chỉ sau khi cột khớp mới so các con số. Nếu không khớp, nêu rõ khác biệt nào có thể giải thích chênh lệch và khác biệt nào cần xác minh.\n\n### Hai bản ghi cần so\n- Bản A · Kỳ 09 · doanh thu gộp\n- Bản B · Kỳ 09 · doanh thu thuần\n- Điểm lệch · Định nghĩa chỉ tiêu\nBảng so nhấn mạnh khác biệt định nghĩa trước khi tính chênh lệch.\n\n### Tự kiểm tra\nTạo ba cột so sánh quan trọng nhất của ca học.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S05","title":"Không đồng nhất nhấp, phiên và người dùng","content":"Một lượt nhấp quảng cáo là hành động trên nền tảng quảng cáo; phiên và người dùng là chỉ số của công cụ phân tích với phạm vi đo riêng. Chênh lệch không tự chứng minh lỗi. Cần kiểm tra thẻ đo, UTM, múi giờ, bộ lọc và phạm vi báo cáo trước khi giải thích.\n\n### Ba đơn vị khác nhau\n- Nhấp · 1.200 · nền tảng quảng cáo\n- Phiên · 980 · GA4\n- Người mới · 740 · GA4\nBa ô số giả lập dùng ba đơn vị đếm khác nhau, không phải ba giai đoạn của cùng một phễu đã đối soát.\n\n### Tự kiểm tra\nNói vì sao 1.200 nhấp không thể lấy trừ trực tiếp 980 phiên để kết luận mất 220 người.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S06","title":"Giả thuyết phải có phép kiểm tra","content":"Với mỗi nguyên nhân dự đoán, ghi cách kiểm chứng. Nếu nghi lệch kỳ, so múi giờ và ngày chốt; nếu nghi thiếu UTM, kiểm tra liên kết; nếu nghi bản ghi trùng, xem mã giao dịch hoặc lead. Đừng kết luận lỗi hệ thống chỉ từ hai tổng không bằng nhau.\n\n### Giả thuyết có kiểm tra\n- Giả thuyết · Khác múi giờ\n- Phép thử · So ngày theo cùng múi giờ\n- Kết quả · Ghi số dòng thay đổi\nPhiếu giả thuyết buộc người phân tích nêu phép thử thay vì đoán nguyên nhân.\n\n### Tự kiểm tra\nViết một giả thuyết và phép thử tương ứng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S07","title":"Chọn số phù hợp câu hỏi quản lý","content":"Kế toán cần số phù hợp định nghĩa doanh thu và trạng thái hóa đơn; Marketing cần chỉ số đúng mục tiêu chiến dịch. Trình bày cả nguồn không chọn và lý do. Khi chưa thể hòa giải, dùng hai kịch bản có điều kiện hoặc nêu bước xác minh tiếp. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nChọn chỉ số cho quyết định và nêu một giới hạn.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S08","title":"Viết một brief không che giấu bất định","content":"Brief một trang nên có câu hỏi, bảng nguồn, chênh lệch được giải thích, điều chưa giải thích và khuyến nghị. Người đọc phải phân biệt quan sát thực tế với giả định. Dùng câu kết luận có điều kiện nếu một định nghĩa hoặc nguồn vẫn chưa được xác nhận.\n\n### Brief quyết định\n- 01 · Nguồn · Định nghĩa · kỳ\n- 02 · Đối chiếu · Khớp và chưa khớp\n- 03 · Đề xuất · Có điều kiện\nBa phần cốt lõi của brief kết nối nguồn, phân tích và hành động.\n\n### Tự kiểm tra\nViết khuyến nghị hai câu với điều kiện áp dụng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S09","title":"Làm mẫu · Lập bảng so hai báo cáo không đồng nhất","content":"Báo cáo A là doanh thu đã ghi nhận, báo cáo B là hóa đơn đã xuất. Hai tổng có thể lệch vì hóa đơn hủy hoặc thời điểm ghi nhận. Tương tự, lượt nhấp quảng cáo, phiên GA4 và người dùng mới là ba đơn vị đếm khác nhau; không lấy trung bình hay trừ trực tiếp để gọi là “sai lệch”. Bảng so phải có cột đơn vị đếm, kỳ, bộ lọc, trạng thái và nguồn gốc. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S10","title":"Tự làm · Lập bảng so hai báo cáo không đồng nhất","content":"Giải thích chênh lệch bằng định nghĩa, phạm vi, kỳ và trạng thái trước khi khuyến nghị. Thực hiện theo bốn bước: 1) Chọn ba nguồn cùng chủ đề; ghi số, đơn vị đếm và loại nguồn sơ cấp/thứ cấp. 2) So tác giả, thời điểm, mục đích, bằng chứng, khả năng kiểm chứng, định nghĩa và kỳ. 3) Truy một bản ghi/hóa đơn/chiến dịch mẫu để xác minh nguyên nhân chênh lệch. 4) Viết khuyến nghị có điều kiện và một bước đối soát tiếp. Sản phẩm cần tạo: Ma trận ba nguồn theo năm tiêu chí, bảng giải thích chênh lệch và brief quyết định một trang.\n\n### Bốn bước thực hành\n- 01 · Chọn ba nguồn cùng chủ đề; ghi số, đơn vị đếm và loại nguồn sơ cấp/thứ cấp.\n- 02 · So tác giả, thời điểm, mục đích, bằng chứng, khả năng kiểm chứng, định nghĩa và kỳ.\n- 03 · Truy một bản ghi/hóa đơn/chiến dịch mẫu để xác minh nguyên nhân chênh lệch.\n- 04 · Viết khuyến nghị có điều kiện và một bước đối soát tiếp.\nQuy trình thực hành lập bảng so hai báo cáo không đồng nhất có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-I/M02/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Không so trực tiếp các chỉ số khác phạm vi. Mỗi nguyên nhân chênh lệch có bằng chứng hoặc được ghi là giả định. Kết luận cho biết số nào dùng được cho câu hỏi nào. Lỗi thường gặp: Lấy trung bình hai tổng khi một số gồm giao dịch hủy còn số kia không. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Không so trực tiếp các chỉ số khác phạm vi.\n- Tiêu chí 2 · Mỗi nguyên nhân chênh lệch có bằng chứng hoặc được ghi là giả định.\n- Tiêu chí 3 · Kết luận cho biết số nào dùng được cho câu hỏi nào.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"}],"questions":[{"code":"M1-I/M02/GENERAL/Q01","text":"Hai báo cáo cho cùng tên chỉ tiêu nhưng khác số. Bước đầu là gì?","explanation":"Khác biệt phạm vi hoặc phương pháp phải được giải thích trước khi chọn số.","options":["Chọn số cao hơn","So định nghĩa, kỳ và phạm vi đo","Lấy trung bình cộng"],"correctIndex":1},{"code":"M1-I/M02/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-I/M02/GENERAL/Q03","text":"Hai báo cáo cùng tên “doanh thu” nhưng khác tổng. Kiểm tra gì trước?","explanation":"Tên chỉ số giống nhau chưa bảo đảm cùng cách đo.","options":["Màu biểu đồ","Định nghĩa gộp/thuần, kỳ, trạng thái giao dịch và phạm vi","Chọn số trung bình"],"correctIndex":1},{"code":"M1-I/M02/GENERAL/Q04","text":"Một ảnh biểu đồ không ghi kỳ và mẫu số. Bạn nên?","explanation":"Bản gốc và phương pháp là căn cứ của con số.","options":["Dùng để chốt báo cáo","Tìm báo cáo gốc và xác nhận định nghĩa trước khi dùng","Ước lượng mẫu số theo hình"],"correctIndex":1},{"code":"M1-I/M02/GENERAL/Q05","text":"Khi chưa hòa giải được hai số, báo cáo nên viết gì?","explanation":"Bất định cần thể hiện rõ cho người ra quyết định.","options":["Một số duy nhất không chú thích","Hai kịch bản có điều kiện cùng bước xác minh tiếp","Bỏ hẳn phần số liệu"],"correctIndex":1}]},{"title":"Tổ chức và quản lý kho thông tin","description":"Thiết kế thư mục, sổ đăng ký và quyền truy cập cho nhóm.","purpose":{"title":"Tạo sổ đăng ký nguồn và ma trận quyền","goal":"Giữ định nghĩa, chủ sở hữu và lịch sử thay đổi của các nguồn dùng trong báo cáo.","example":"Sổ đăng ký cho một báo cáo cần ghi tên hệ thống, người tạo, định nghĩa chỉ số, kỳ, URL/mã tệp, phiên bản và người phê duyệt. Bảng đối chiếu chỉ người phụ trách được sửa; quản lý nhận bản đọc. Khi dữ liệu kỳ trước được cập nhật, tạo dòng phiên bản mới và nêu tác động tới kết luận cũ thay vì ghi đè âm thầm.","steps":["Thiết kế cây thư mục tối đa bốn cấp và sổ đăng ký tối thiểu 20 tài liệu giả lập với tên, chủ đề, phiên bản, người phụ trách.","Gán chủ sở hữu, người duyệt và người chỉ xem; ghi nơi lưu bản sao có thể khôi phục.","Mô phỏng nguồn A đổi định nghĩa hoặc phiên bản; ghi tác động.","Kiểm tra một đồng nghiệp có thể dựng lại báo cáo theo sổ đăng ký và quy tắc phân loại."],"output":"Ảnh hoặc sơ đồ thư mục tối đa bốn cấp, sổ đăng ký ít nhất 20 dòng, ma trận quyền và quy tắc phân loại.","checks":["Nguồn có định nghĩa, kỳ và phiên bản.","Quyền sửa được giới hạn theo trách nhiệm.","Số cũ có thể giải thích sau khi nguồn thay đổi."],"mistake":"Chia sẻ liên kết sửa cho cả phòng ban để “tiện” rồi không biết ai đổi dữ liệu.","minutes":55,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":55,"slides":[{"code":"M1-I/M03/S01","title":"Một nguyên tắc phân loại","content":"Chọn cách phân loại chính theo dự án hoặc loại hồ sơ rồi dùng nhất quán. Tránh pha hai cách cùng cấp khiến người dùng không biết lưu ở đâu. Giữ cây thư mục đủ nông để người khác tìm được.\n\n### Một cây thư mục nhất quán\n- Chiến dịch 2026 · Thư mục gốc\n- 01_Nguồn · Tệp gốc\n- 02_Phân tích · Bản làm việc\n- 03_Duyệt · Bản chốt\nCây thư mục ví dụ được sắp theo một nguyên tắc từ nguồn tới bản duyệt.\n\n### Tự kiểm tra\nVẽ cấu trúc thư mục cho một chu kỳ công việc.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S02","title":"Thư mục chưa đủ để quản lý","content":"Sổ đăng ký ghi tên, phiên bản, nguồn, kỳ dữ liệu, chủ sở hữu, mức nhạy cảm và liên kết. Nó giúp tra cứu theo thuộc tính mà cây thư mục không thể hiện hết. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Sổ đăng ký dữ liệu\n- Tên · KPI_09_2026\n- Nguồn · Hệ thống gốc\n- Phiên bản · v02 · 02/10/2026\nBa trường mẫu trong sổ đăng ký liên kết tệp với nguồn và phiên bản.\n\n### Tự kiểm tra\nLiệt kê các trường bắt buộc của sổ đăng ký.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S03","title":"Cấp đúng người, đúng mục đích","content":"Áp dụng quyền tối thiểu: mỗi người chỉ có quyền đủ để làm phần việc. Đồng bộ tệp không thay thế bản sao lưu; một thay đổi sai cũng có thể đồng bộ sang các bản khác.\n\n### Quyền theo nhiệm vụ\n- Người soạn · Được sửa bản làm việc\n- Người duyệt · Được xem và duyệt\n- Người đọc · Chỉ xem bản đã chốt\nBa mức quyền minh họa nguyên tắc chỉ cấp quyền cần cho công việc.\n\n### Tự kiểm tra\nNêu ai được xem, ai được sửa và nơi sao lưu.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S04","title":"Một kho thông tin cần quy ước chung","content":"Chọn cách phân loại phản ánh hành trình công việc: nguồn gốc, bản đang xử lý, bản duyệt và lưu trữ. Tránh để mỗi cá nhân tạo một cây riêng. Khi một tệp thuộc nhiều chủ đề, lưu một bản chính và dùng metadata hoặc liên kết để tìm lại, giảm trùng lặp.\n\n### Một bản chính\n- Kho dữ liệu · Gốc\n- 01_Nguồn · Bản chính\n- 02_Làm-việc · Bản phân tích\n- 03_Duyệt · Bản công bố\nCây thư mục thể hiện một bản chính và các trạng thái xử lý.\n\n### Tự kiểm tra\nĐề xuất thư mục gốc và ba thư mục con.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S05","title":"Sổ đăng ký giúp tìm bằng thuộc tính","content":"Bên cạnh đường dẫn, ghi tên bộ dữ liệu, hệ thống nguồn, chủ sở hữu, kỳ, phiên bản, ngày cập nhật và mức nhạy cảm. Nhờ vậy người dùng biết bảng nào đã chốt và hỏi ai khi có sai lệch. Không dùng tên file “mới nhất” như một trường trạng thái đáng tin.\n\n### Một dòng sổ đăng ký\n- Bộ dữ liệu · Báo cáo kỳ 09\n- Nguồn · Hệ thống chính\n- Chủ sở hữu · Người chịu trách nhiệm\n- Phiên bản · v02 · đã duyệt\nDòng metadata mẫu làm rõ nguồn, người phụ trách và phiên bản của báo cáo.\n\n### Tự kiểm tra\nChọn bảy trường sổ đăng ký cho ca học.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S06","title":"Quyền xem không đồng nghĩa quyền sửa","content":"Gắn quyền cho vai trò thực tế: người soạn sửa bản làm việc, người duyệt đọc và phê duyệt, người nhận chỉ xem bản chốt. Kiểm tra nơi lưu bản sao và khả năng khôi phục. Đồng bộ tệp là cơ chế cập nhật giữa thiết bị, không thay thế kiểm tra sao lưu.\n\n### Ma trận quyền\n- Soạn · Sửa bản làm việc\n- Duyệt · Xem · xác nhận\n- Nhận · Xem bản chốt\nBa hàng quyền được gắn với nhiệm vụ cụ thể, không cấp quản trị cho mọi người.\n\n### Tự kiểm tra\nPhân hai quyền và một người chịu trách nhiệm sao lưu.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S07","title":"Tổ chức hồ sơ để người khác kiểm tra","content":"Với Kế toán, sổ đăng ký nối số chứng từ, bút toán và trạng thái điều chỉnh. Với Marketing, nối mã chiến dịch, nguồn GA4, quy ước UTM và thời điểm xuất báo cáo. Cả hai cần người phụ trách định nghĩa chỉ số, không chỉ một thư mục đẹp. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nGhi khóa liên kết giữa hai hệ thống của ca học.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S08","title":"Thử tình huống bàn giao nhóm","content":"Một đồng nghiệp mới phải tìm được báo cáo đúng kỳ, mở nguồn gốc và biết ai phê duyệt mà không hỏi tác giả. Nếu không làm được, cần sửa sổ đăng ký, đường dẫn hoặc quyền. Đây là kiểm thử quản lý thông tin, không chỉ kiểm tra kỹ năng đặt tên.\n\n### Kiểm tra bàn giao\n- 01 · Tìm · Theo mã · kỳ\n- 02 · Mở · Đúng nguồn và bản\n- 03 · Xác nhận · Người duyệt\nBa bước kiểm thử giúp đánh giá kho thông tin có dùng được bởi người khác.\n\n### Tự kiểm tra\nNhờ người khác tìm một bộ dữ liệu từ mã và kỳ.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S09","title":"Làm mẫu · Tạo sổ đăng ký nguồn và ma trận quyền","content":"Sổ đăng ký cho một báo cáo cần ghi tên hệ thống, người tạo, định nghĩa chỉ số, kỳ, URL/mã tệp, phiên bản và người phê duyệt. Bảng đối chiếu chỉ người phụ trách được sửa; quản lý nhận bản đọc. Khi dữ liệu kỳ trước được cập nhật, tạo dòng phiên bản mới và nêu tác động tới kết luận cũ thay vì ghi đè âm thầm. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S10","title":"Tự làm · Tạo sổ đăng ký nguồn và ma trận quyền","content":"Giữ định nghĩa, chủ sở hữu và lịch sử thay đổi của các nguồn dùng trong báo cáo. Thực hiện theo bốn bước: 1) Thiết kế cây thư mục tối đa bốn cấp và sổ đăng ký tối thiểu 20 tài liệu giả lập với tên, chủ đề, phiên bản, người phụ trách. 2) Gán chủ sở hữu, người duyệt và người chỉ xem; ghi nơi lưu bản sao có thể khôi phục. 3) Mô phỏng nguồn A đổi định nghĩa hoặc phiên bản; ghi tác động. 4) Kiểm tra một đồng nghiệp có thể dựng lại báo cáo theo sổ đăng ký và quy tắc phân loại. Sản phẩm cần tạo: Ảnh hoặc sơ đồ thư mục tối đa bốn cấp, sổ đăng ký ít nhất 20 dòng, ma trận quyền và quy tắc phân loại.\n\n### Bốn bước thực hành\n- 01 · Thiết kế cây thư mục tối đa bốn cấp và sổ đăng ký tối thiểu 20 tài liệu giả lập với tên, chủ đề, phiên bản, người phụ trách.\n- 02 · Gán chủ sở hữu, người duyệt và người chỉ xem; ghi nơi lưu bản sao có thể khôi phục.\n- 03 · Mô phỏng nguồn A đổi định nghĩa hoặc phiên bản; ghi tác động.\n- 04 · Kiểm tra một đồng nghiệp có thể dựng lại báo cáo theo sổ đăng ký và quy tắc phân loại.\nQuy trình thực hành tạo sổ đăng ký nguồn và ma trận quyền có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"},{"code":"M1-I/M03/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Nguồn có định nghĩa, kỳ và phiên bản. Quyền sửa được giới hạn theo trách nhiệm. Số cũ có thể giải thích sau khi nguồn thay đổi. Lỗi thường gặp: Chia sẻ liên kết sửa cho cả phòng ban để “tiện” rồi không biết ai đổi dữ liệu. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Nguồn có định nghĩa, kỳ và phiên bản.\n- Tiêu chí 2 · Quyền sửa được giới hạn theo trách nhiệm.\n- Tiêu chí 3 · Số cũ có thể giải thích sau khi nguồn thay đổi.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nNIST · Nguyên tắc quyền tối thiểu\nhttps://csrc.nist.gov/glossary/term/least_privilege"}],"questions":[{"code":"M1-I/M03/GENERAL/Q01","text":"Đồng nghiệp chỉ cần đọc báo cáo đã duyệt. Quyền nào phù hợp?","explanation":"Quyền tối thiểu chỉ cấp mức cần để thực hiện công việc.","options":["Chỉnh sửa cả thư mục nguồn","Quyền xem bản đã duyệt","Quyền quản trị hệ thống"],"correctIndex":1},{"code":"M1-I/M03/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-I/M03/GENERAL/Q03","text":"Sổ đăng ký nguồn cần ghi bộ thông tin nào?","explanation":"Sổ đăng ký cần đủ thông tin truy vết và quản lý truy cập.","options":["Tên nguồn, chủ sở hữu, kỳ, định nghĩa, phiên bản và quyền","Chỉ tên người tải","Chỉ đường dẫn chia sẻ công khai"],"correctIndex":0},{"code":"M1-I/M03/GENERAL/Q04","text":"Một tệp chứa dữ liệu nhân sự chỉ người phụ trách cần sửa. Thiết lập nào đúng?","explanation":"Quyền theo vai trò và nhu cầu sử dụng, tránh cấp rộng.","options":["Ai có link cũng sửa được","Người phụ trách sửa; người cần đối chiếu chỉ xem phần phù hợp","Không ai được xem kể cả người phụ trách"],"correctIndex":1},{"code":"M1-I/M03/GENERAL/Q05","text":"Báo cáo tháng trước bị thay mà không ghi phiên bản. Rủi ro chính?","explanation":"Lịch sử thay đổi giúp kiểm tra và giải thích quyết định đã đưa ra.","options":["Màu sắc thay đổi","Không giải thích được vì sao kết quả cũ và mới khác nhau","Tên tệp ngắn hơn"],"correctIndex":1}]}],"assignments":{"general":{"title":"Bài cuối khóa M1-I · vị trí của bạn","situation":"Áp dụng vào một quyết định thực tế của vị trí.","prompt":"Nêu nhu cầu, nguồn, cách kiểm tra, sản phẩm công việc và kết luận có giới hạn.","deliverables":["Nhật ký nguồn và định nghĩa","Sản phẩm công việc có thể kiểm tra","Giới hạn và đề xuất tiếp theo"],"caseFacts":[],"rubric":[["Nhu cầu thông tin đầy đủ, cụ thể",20],["Chiến lược tìm kiếm: ≥8 truy vấn, ≥4 toán tử",25],["Chất lượng nguồn: ≥2 sơ cấp, đánh giá đầy đủ",20],["Bảng so sánh, phát hiện khác biệt",20],["Khuyến nghị có căn cứ",15]],"pass":70,"minimumCriterion":null,"requirements":["Viết nhu cầu thông tin có phạm vi, thời gian, mức chi tiết và sản phẩm đầu ra; lập ma trận từ khóa.","Ghi nhật ký ít nhất 8 truy vấn, sử dụng ít nhất 4 dạng toán tử hoặc cách lọc có giải thích.","Thu thập 5 nguồn, trong đó ít nhất 2 nguồn sơ cấp; so sánh định nghĩa, kỳ và phương pháp của chỉ số quan trọng.","Nộp brief 1 trang: điều đã biết, điều còn tranh cãi, con số hoặc khoảng giá trị khuyến nghị và lý do."]},"accounting":{"title":"Bài cuối khóa M1-I · Kế toán","situation":"Sổ cái ghi doanh thu tháng 9 khác bảng tổng hợp hóa đơn cùng kỳ.","prompt":"Lập kế hoạch tìm và đối chiếu doanh thu giả lập giữa sổ cái, hóa đơn và bảng điều chỉnh; nêu khoản chênh có thể truy vết.","deliverables":["Nhu cầu thông tin và nhật ký truy vấn","Bảng nguồn–định nghĩa–kỳ–chênh lệch","Kết luận một trang kèm giới hạn"],"caseFacts":["Sổ cái tháng 09/2026: 125.000.000 đ; định nghĩa gồm doanh thu đã ghi nhận","Tổng hóa đơn xuất tháng 09/2026: 130.000.000 đ; có hóa đơn HD031 trị giá 5.000.000 đ đã hủy","Bảng điều chỉnh: HD031 · hủy ngày 29/09/2026 · lý do xuất trùng","Câu hỏi: chênh lệch 5.000.000 đ có thể giải thích được không và cần kiểm tra gì tiếp?"],"rubric":[["Nhu cầu thông tin đầy đủ, cụ thể",20],["Chiến lược tìm kiếm: ≥8 truy vấn, ≥4 toán tử",25],["Chất lượng nguồn: ≥2 sơ cấp, đánh giá đầy đủ",20],["Bảng so sánh, phát hiện khác biệt",20],["Khuyến nghị có căn cứ",15]],"pass":70,"minimumCriterion":null,"requirements":["Viết nhu cầu thông tin có phạm vi, thời gian, mức chi tiết và sản phẩm đầu ra; lập ma trận từ khóa.","Ghi nhật ký ít nhất 8 truy vấn, sử dụng ít nhất 4 dạng toán tử hoặc cách lọc có giải thích.","Thu thập 5 nguồn, trong đó ít nhất 2 nguồn sơ cấp; so sánh định nghĩa, kỳ và phương pháp của chỉ số quan trọng.","Nộp brief 1 trang: điều đã biết, điều còn tranh cãi, con số hoặc khoảng giá trị khuyến nghị và lý do."]},"marketing":{"title":"Bài cuối khóa M1-I · Marketing","situation":"Báo cáo nền tảng quảng cáo ghi 1.200 lượt nhấp, GA4 ghi 980 phiên và 740 người dùng.","prompt":"So báo cáo nguồn truy cập GA4 với nền tảng quảng cáo cho chiến dịch giả lập; giải thích khác biệt giữa nhấp, phiên và người dùng.","deliverables":["Kế hoạch tìm và nhật ký truy vấn","Bảng so chỉ số/phạm vi/kỳ/nguồn","Khuyến nghị một trang cho quyết định tối ưu chiến dịch"],"caseFacts":["Nền tảng quảng cáo: 1.200 lượt nhấp vào quảng cáo trong kỳ 01–30/09/2026","GA4 Traffic acquisition: 980 phiên được ghi nhận cho chiến dịch trong cùng kỳ","GA4 User acquisition: 740 người dùng mới có nguồn đầu tiên từ chiến dịch","Chưa đối soát UTM, múi giờ, bộ lọc và cơ chế đo; các số trên không cùng đơn vị đếm"],"rubric":[["Nhu cầu thông tin đầy đủ, cụ thể",20],["Chiến lược tìm kiếm: ≥8 truy vấn, ≥4 toán tử",25],["Chất lượng nguồn: ≥2 sơ cấp, đánh giá đầy đủ",20],["Bảng so sánh, phát hiện khác biệt",20],["Khuyến nghị có căn cứ",15]],"pass":70,"minimumCriterion":null,"requirements":["Viết nhu cầu thông tin có phạm vi, thời gian, mức chi tiết và sản phẩm đầu ra; lập ma trận từ khóa.","Ghi nhật ký ít nhất 8 truy vấn, sử dụng ít nhất 4 dạng toán tử hoặc cách lọc có giải thích.","Thu thập 5 nguồn, trong đó ít nhất 2 nguồn sơ cấp; so sánh định nghĩa, kỳ và phương pháp của chỉ số quan trọng.","Nộp brief 1 trang: điều đã biết, điều còn tranh cãi, con số hoặc khoảng giá trị khuyến nghị và lý do."]},"hr":{"title":"Bài cuối khóa M1-I · Nhân sự","situation":"HRIS và bảng lương cho số nhân viên đang làm việc khác nhau ở cuối tháng.","prompt":"Đối chiếu số nhân viên giả lập giữa HRIS và bảng lương, ghi khác biệt định nghĩa/kỳ.","deliverables":["Nhu cầu và truy vấn","Bảng đối chiếu theo trạng thái","Kết luận và quyền truy cập"],"caseFacts":["HRIS · chốt 30/09/2026 · 48 nhân viên trạng thái đang làm việc","Bảng lương tháng 09/2026 · 49 người có phát sinh lương","NV019 nghỉ ngày 20/09 nhưng vẫn có lương 20 ngày trong kỳ","Hai nguồn khác nhau về nghĩa “đang làm việc tại ngày chốt” và “có lương trong kỳ”"],"rubric":[["Nhu cầu thông tin đầy đủ, cụ thể",20],["Chiến lược tìm kiếm: ≥8 truy vấn, ≥4 toán tử",25],["Chất lượng nguồn: ≥2 sơ cấp, đánh giá đầy đủ",20],["Bảng so sánh, phát hiện khác biệt",20],["Khuyến nghị có căn cứ",15]],"pass":70,"minimumCriterion":null,"requirements":["Viết nhu cầu thông tin có phạm vi, thời gian, mức chi tiết và sản phẩm đầu ra; lập ma trận từ khóa.","Ghi nhật ký ít nhất 8 truy vấn, sử dụng ít nhất 4 dạng toán tử hoặc cách lọc có giải thích.","Thu thập 5 nguồn, trong đó ít nhất 2 nguồn sơ cấp; so sánh định nghĩa, kỳ và phương pháp của chỉ số quan trọng.","Nộp brief 1 trang: điều đã biết, điều còn tranh cãi, con số hoặc khoảng giá trị khuyến nghị và lý do."]},"sales":{"title":"Bài cuối khóa M1-I · Sales/CRM","situation":"CRM và báo cáo đơn hàng cho hai tỷ lệ chuyển đổi khác nhau.","prompt":"Đối chiếu tỷ lệ chuyển đổi giả lập giữa CRM và báo cáo đơn hàng.","deliverables":["Định nghĩa và truy vấn","Bảng đối chiếu giao dịch","Khuyến nghị cách đo thống nhất"],"caseFacts":["CRM tháng 09/2026 · 80 lead mới; 32 chuyển thành cơ hội","Hệ thống đơn hàng · 18 đơn tạo; 17 hoàn tất và 1 đơn hủy","Báo cáo A gọi “chuyển đổi” là cơ hội/lead = 32/80","Báo cáo B gọi “chuyển đổi” là đơn hoàn tất/lead = 17/80"],"rubric":[["Nhu cầu thông tin đầy đủ, cụ thể",20],["Chiến lược tìm kiếm: ≥8 truy vấn, ≥4 toán tử",25],["Chất lượng nguồn: ≥2 sơ cấp, đánh giá đầy đủ",20],["Bảng so sánh, phát hiện khác biệt",20],["Khuyến nghị có căn cứ",15]],"pass":70,"minimumCriterion":null,"requirements":["Viết nhu cầu thông tin có phạm vi, thời gian, mức chi tiết và sản phẩm đầu ra; lập ma trận từ khóa.","Ghi nhật ký ít nhất 8 truy vấn, sử dụng ít nhất 4 dạng toán tử hoặc cách lọc có giải thích.","Thu thập 5 nguồn, trong đó ít nhất 2 nguồn sơ cấp; so sánh định nghĩa, kỳ và phương pháp của chỉ số quan trọng.","Nộp brief 1 trang: điều đã biết, điều còn tranh cãi, con số hoặc khoảng giá trị khuyến nghị và lý do."]},"ceo":{"title":"Bài cuối khóa M1-I · CEO","situation":"Báo cáo thị trường và báo cáo nội bộ đưa ra hai dự báo tăng trưởng khác nhau.","prompt":"So hai dự báo giả lập và viết một trang phương án quyết định.","deliverables":["Ma trận nguồn","Bảng giả định khác biệt","Khuyến nghị có giới hạn"],"caseFacts":["Báo cáo ngoài dự báo tăng trưởng năm 2026 là 12% cho toàn ngành","Báo cáo nội bộ tăng 8% trong 9 tháng đầu 2026 cho một nhóm sản phẩm","Hai số khác phạm vi và kỳ; không thể lấy trung bình thành dự báo công ty","Quyết định thử thị trường cần thêm chi phí, biên lợi nhuận và kịch bản thận trọng"],"rubric":[["Nhu cầu thông tin đầy đủ, cụ thể",20],["Chiến lược tìm kiếm: ≥8 truy vấn, ≥4 toán tử",25],["Chất lượng nguồn: ≥2 sơ cấp, đánh giá đầy đủ",20],["Bảng so sánh, phát hiện khác biệt",20],["Khuyến nghị có căn cứ",15]],"pass":70,"minimumCriterion":null,"requirements":["Viết nhu cầu thông tin có phạm vi, thời gian, mức chi tiết và sản phẩm đầu ra; lập ma trận từ khóa.","Ghi nhật ký ít nhất 8 truy vấn, sử dụng ít nhất 4 dạng toán tử hoặc cách lọc có giải thích.","Thu thập 5 nguồn, trong đó ít nhất 2 nguồn sơ cấp; so sánh định nghĩa, kỳ và phương pháp của chỉ số quan trọng.","Nộp brief 1 trang: điều đã biết, điều còn tranh cãi, con số hoặc khoảng giá trị khuyến nghị và lý do."]}}},{"code":"M1-A","tier":3,"title":"Phân tích thông tin và quản trị dữ liệu","description":"Dẫn dắt nghiên cứu đa nguồn, đo chất lượng dữ liệu và thiết lập chuẩn quản trị cho quyết định quan trọng.","purpose":"Bậc 5–6 · 9 giờ","modules":[{"title":"Nghiên cứu phức hợp đa nguồn","description":"Thiết kế nghiên cứu cho quyết định có dữ liệu nội bộ và bên ngoài.","purpose":{"title":"Thiết kế bản đồ nguồn cho một quyết định","goal":"Chuyển quyết định thành chỉ số, nguồn, giả định và phép thử độ nhạy.","example":"Quyết định mở rộng thị trường cần ít nhất hai phương án và điều kiện chọn. Nguồn thị trường cho bối cảnh, dữ liệu bán hàng cho nhu cầu thực tế, tài chính cho khả năng chi trả. Tam giác hóa đòi hỏi ít nhất ba nguồn gốc độc lập nếu muốn xác lập một khoảng có kiểm chứng; ba báo cáo cùng trích một bảng khảo sát chỉ là một nguồn gốc. Hãy tính kết luận dưới kịch bản cơ sở và thận trọng; chỉ ra giả định nào làm đổi phương án.","steps":["Vẽ hai phương án và một điều kiện tạm hoãn.","Nối từng tiêu chí với ít nhất một nguồn nội bộ và một nguồn bên ngoài, kỳ và người sở hữu.","Đánh dấu nguồn sao chép, khóa nối chưa xác minh và dữ liệu còn thiếu.","Viết hai kịch bản, ngưỡng làm đổi khuyến nghị và mẫu hướng dẫn một đồng nghiệp kiểm tra lại nguồn."],"output":"Cây quyết định, bản đồ nguồn và memo nêu giả định/độ bất định.","checks":["Mỗi dữ liệu thu thập có vai trò trong quyết định.","Nguồn độc lập được phân biệt với bản sao.","Khuyến nghị nêu điều kiện và việc cần đo tiếp."],"mistake":"Dùng một con số dự báo duy nhất mà không cho thấy giả định quan trọng.","minutes":65,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":65,"slides":[{"code":"M1-A/M01/S01","title":"Bắt đầu bằng quyết định cần hỗ trợ","content":"Nêu quyết định, phương án có thể chọn, ngưỡng rủi ro, chỉ tiêu và thời hạn. Tách điều đã biết, giả định và dữ liệu còn thiếu. Không thu thập “mọi thứ” khi chưa biết kết quả dùng để quyết định gì.\n\n### Nghiên cứu bắt đầu ở quyết định\n- Quyết định · Có mở rộng thị trường?\n- Chỉ tiêu · Nhu cầu · chi phí · rủi ro\n- Thời điểm · Trước kỳ ngân sách\nKhung quyết định xác định câu hỏi, tiêu chí và hạn trước khi thu thập.\n\n### Tự kiểm tra\nViết một câu quyết định và hai chỉ tiêu.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S02","title":"Phối hợp nội bộ và bên ngoài","content":"Nguồn bên ngoài cho bối cảnh thị trường hoặc chuẩn tham chiếu; nguồn nội bộ cho vị thế thực tế của doanh nghiệp. Đánh dấu mức độc lập và phương pháp từng nguồn. Ba bản sao của một báo cáo không phải ba nguồn độc lập. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Bản đồ nguồn độc lập\n- Bên ngoài · Bối cảnh thị trường\n- Nội bộ · Bán hàng · tài chính\n- Đối chiếu · Phương pháp · phạm vi\nHai nhóm nguồn ngoài/nội bộ cùng đi vào bước đối chiếu; bản sao cùng nguồn không được tính độc lập.\n\n### Tự kiểm tra\nVẽ bản đồ nguồn và điểm thiếu bằng chứng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S03","title":"Trình bày khoảng trống và giả định","content":"Khi dữ liệu thiếu, công bố khoảng trống, đề xuất cách bổ sung hoặc ước lượng có điều kiện. Dùng nhiều nguồn độc lập để kiểm tra chéo hướng kết luận, nhưng không gọi số nguồn là bằng chứng chắc chắn nếu định nghĩa vẫn khác.\n\n### Nơi chưa chắc chắn\n- Đã biết · Nguồn và định nghĩa rõ\n- Giả định · Cần thử độ nhạy\n- Thiếu · Cần thu thập tiếp\nBa ô tách dữ liệu đã xác nhận, giả định và khoảng trống cần bổ sung.\n\n### Tự kiểm tra\nNêu giới hạn có thể làm đổi quyết định.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S04","title":"Phân rã quyết định thành câu hỏi dữ liệu","content":"Viết các phương án có thể chọn, điều kiện để chọn mỗi phương án và rủi ro của quyết định sai. Từ đó suy ra chỉ tiêu cần đo, nguồn và độ mới mong muốn. Không thu thập một trường dữ liệu chỉ vì nó sẵn có nếu không biết nó đổi quyết định nào.\n\n### Cây quyết định nhỏ\n- Phương án A · Nếu nhu cầu và năng lực đủ\n- Phương án B · Nếu chi phí vượt ngưỡng\n- Tạm hoãn · Nếu dữ liệu chất lượng thấp\nBa nhánh quyết định gắn điều kiện dữ liệu và lựa chọn hành động.\n\n### Tự kiểm tra\nNêu một chỉ tiêu có thể làm đổi phương án.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S05","title":"Phối hợp nguồn nhưng không đếm bản sao","content":"Nguồn nội bộ cho thấy thực lực; nguồn ngoài cho bối cảnh hoặc chuẩn. Ghi hệ thống nào tạo số, ai xuất báo cáo và phương pháp. Nếu ba trang đều lấy một bảng, chúng là một đường nguồn. Cần ưu tiên nguồn thu thập độc lập cho kiểm tra chéo.\n\n### Ba hệ thống, hai loại nguồn\n- Ngoài · Bối cảnh ngành\n- Nội bộ A · Giao dịch\n- Nội bộ B · Vận hành\n- Quyết định · Đối chiếu phạm vi\nSơ đồ ba nguồn đi vào cùng quyết định nhưng giữ rõ nguồn gốc từng hệ thống.\n\n### Tự kiểm tra\nVẽ sơ đồ nguồn gốc của ba báo cáo.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S06","title":"Tính độ nhạy của kết luận","content":"Nếu một chỉ số quan trọng chỉ là ước lượng, hãy tính kết luận trong ít nhất hai giả định hợp lý. Đánh dấu giả định nào khiến phương án đổi. Chỉ trình bày một con số đẹp sẽ che rủi ro; một khoảng có điều kiện giúp người ra quyết định biết cần thu thập gì tiếp.\n\n### Hai kịch bản\n- Thận trọng · Chi phí cao · nhu cầu thấp\n- Cơ sở · Theo dữ liệu đã xác nhận\n- Điểm đổi · Ngưỡng quyết định\nBa thẻ so hai kịch bản và chỉ ra điểm mà khuyến nghị có thể thay đổi.\n\n### Tự kiểm tra\nNêu một giả định làm đổi khuyến nghị.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S07","title":"Lập bản đồ nguồn cho đúng quyết định","content":"Kế toán có thể nối sổ cái, hóa đơn và ngân hàng; Marketing nối GA4, quảng cáo và CRM. Với mỗi nguồn, ghi định nghĩa, kỳ, khóa nối và chất lượng sơ bộ. Nếu không có khóa nối tin cậy, không hợp nhất dòng dữ liệu bằng tên gần giống. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nNêu khóa nối nào đã xác minh và khóa nào chưa.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S08","title":"Để lãnh đạo thấy cả điều chưa biết","content":"Bản nghiên cứu cần một trang đầu nêu quyết định, kết quả chính, độ chắc chắn, giả định và việc cần làm tiếp. Phụ lục giữ bảng nguồn và phép tính để kiểm tra. Không dùng thuật ngữ “chắc chắn” khi dữ liệu còn thiếu hoặc các nguồn khác định nghĩa.\n\n### Báo cáo điều hành\n- 01 · Quyết định · Nêu lựa chọn\n- 02 · Căn cứ · Nguồn · bất định\n- 03 · Điều kiện · Kiểm tra tiếp\nBa phần của báo cáo điều hành giúp quyết định và giới hạn cùng hiện ra.\n\n### Tự kiểm tra\nViết một kết luận có mức tin cậy và điều kiện.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S09","title":"Làm mẫu · Thiết kế bản đồ nguồn cho một quyết định","content":"Quyết định mở rộng thị trường cần ít nhất hai phương án và điều kiện chọn. Nguồn thị trường cho bối cảnh, dữ liệu bán hàng cho nhu cầu thực tế, tài chính cho khả năng chi trả. Tam giác hóa đòi hỏi ít nhất ba nguồn gốc độc lập nếu muốn xác lập một khoảng có kiểm chứng; ba báo cáo cùng trích một bảng khảo sát chỉ là một nguồn gốc. Hãy tính kết luận dưới kịch bản cơ sở và thận trọng; chỉ ra giả định nào làm đổi phương án. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S10","title":"Tự làm · Thiết kế bản đồ nguồn cho một quyết định","content":"Chuyển quyết định thành chỉ số, nguồn, giả định và phép thử độ nhạy. Thực hiện theo bốn bước: 1) Vẽ hai phương án và một điều kiện tạm hoãn. 2) Nối từng tiêu chí với ít nhất một nguồn nội bộ và một nguồn bên ngoài, kỳ và người sở hữu. 3) Đánh dấu nguồn sao chép, khóa nối chưa xác minh và dữ liệu còn thiếu. 4) Viết hai kịch bản, ngưỡng làm đổi khuyến nghị và mẫu hướng dẫn một đồng nghiệp kiểm tra lại nguồn. Sản phẩm cần tạo: Cây quyết định, bản đồ nguồn và memo nêu giả định/độ bất định.\n\n### Bốn bước thực hành\n- 01 · Vẽ hai phương án và một điều kiện tạm hoãn.\n- 02 · Nối từng tiêu chí với ít nhất một nguồn nội bộ và một nguồn bên ngoài, kỳ và người sở hữu.\n- 03 · Đánh dấu nguồn sao chép, khóa nối chưa xác minh và dữ liệu còn thiếu.\n- 04 · Viết hai kịch bản, ngưỡng làm đổi khuyến nghị và mẫu hướng dẫn một đồng nghiệp kiểm tra lại nguồn.\nQuy trình thực hành thiết kế bản đồ nguồn cho một quyết định có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"},{"code":"M1-A/M01/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Mỗi dữ liệu thu thập có vai trò trong quyết định. Nguồn độc lập được phân biệt với bản sao. Khuyến nghị nêu điều kiện và việc cần đo tiếp. Lỗi thường gặp: Dùng một con số dự báo duy nhất mà không cho thấy giả định quan trọng. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Mỗi dữ liệu thu thập có vai trò trong quyết định.\n- Tiêu chí 2 · Nguồn độc lập được phân biệt với bản sao.\n- Tiêu chí 3 · Khuyến nghị nêu điều kiện và việc cần đo tiếp.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nỦy ban châu Âu · DigComp 3.0\nhttps://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en"}],"questions":[{"code":"M1-A/M01/GENERAL/Q01","text":"Khi chưa có dữ liệu cho một phần quyết định, cách làm nào minh bạch?","explanation":"Khoảng trống và giả định cần được công bố để người ra quyết định hiểu độ chắc chắn.","options":["Tự điền số hợp lý","Bỏ qua phần đó","Nêu khoảng trống, giả định và cách kiểm tra tiếp"],"correctIndex":2},{"code":"M1-A/M01/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-A/M01/GENERAL/Q03","text":"Thiết kế nghiên cứu cho quyết định đầu tư nên bắt đầu từ đâu?","explanation":"Câu hỏi quyết định định hướng việc cần đo và nguồn cần thu.","options":["Thu mọi bảng đang có","Liệt kê phương án, ngưỡng quyết định, chỉ tiêu và nguồn cần kiểm","Vẽ biểu đồ trước"],"correctIndex":1},{"code":"M1-A/M01/GENERAL/Q04","text":"Ba trang mạng đều sao chép cùng một bảng. Cách tính nguồn độc lập?","explanation":"Bản sao không tạo thêm bằng chứng độc lập.","options":["Ba nguồn","Một nguồn gốc; cần tìm cách thu thập độc lập nếu muốn kiểm tra chéo","Không có nguồn nào"],"correctIndex":1},{"code":"M1-A/M01/GENERAL/Q05","text":"Một giả định làm đảo chiều khuyến nghị. Báo cáo nên?","explanation":"Phân tích độ nhạy cho thấy điều kiện của khuyến nghị.","options":["Ẩn giả định","Trình bày hai kịch bản và ngưỡng làm đổi quyết định","Chỉ giữ kịch bản thuận lợi"],"correctIndex":1}]},{"title":"Đánh giá chất lượng dữ liệu","description":"Đo sáu chiều chất lượng và đề xuất kiểm soát phòng ngừa/phát hiện.","purpose":{"title":"Tính bảng điểm chất lượng có mẫu số","goal":"Đo sáu chiều chất lượng, chọn ngưỡng và giao xử lý ngoại lệ.","example":"Giả sử 100 giao dịch phải có mã chứng từ và 98 giao dịch có mã: độ đầy đủ là 98/100 = 98%. Một mã lặp ảnh hưởng tính duy nhất; email đúng cú pháp nhưng thuộc sai người ảnh hưởng tính chính xác. Ghi rõ mẫu số, kỳ đo, ngoại lệ hợp lệ và chủ sở hữu. Không tô ô xanh nếu chưa có phép đo; lỗi chưa giải quyết cần quyết định dùng dữ liệu có điều kiện hay tạm dừng.","steps":["Chọn tập dữ liệu, thời điểm và sáu chiều: đầy đủ, duy nhất, nhất quán, kịp thời, hợp lệ, chính xác.","Viết tử số, mẫu số/ngưỡng và ít nhất sáu quy tắc kiểm tra có thể áp dụng; phân loại phòng ngừa hoặc phát hiện.","Phân loại một bất thường chưa xác minh và một lỗi đã xác nhận.","Giao người xử lý, hạn đo lại và quyết định dùng hoặc tạm dừng dữ liệu."],"output":"Bảng điểm sáu chiều, ít nhất sáu quy tắc kiểm tra, danh sách ngoại lệ và kế hoạch kiểm soát.","checks":["Tỷ lệ có cả tử số, mẫu số và kỳ.","Hợp lệ định dạng không bị nhầm với chính xác thực tế.","Mỗi ngoại lệ ưu tiên có người xử lý và hạn kiểm tra lại."],"mistake":"Xóa dòng bất thường để bảng đẹp hơn mà không điều tra và lưu dấu vết.","minutes":65,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":65,"slides":[{"code":"M1-A/M02/S01","title":"Dữ liệu có đủ tốt cho mục đích?","content":"Đo độ đầy đủ, duy nhất, nhất quán, kịp thời, hợp lệ và chính xác. Dữ liệu đúng định dạng vẫn có thể sai thực tế; dữ liệu đầy đủ vẫn có thể cũ. Chọn ngưỡng theo rủi ro của quyết định.\n\n### Sáu chiều chất lượng\n- Đủ · Thiếu trường?\n- Duy nhất · Mã trùng?\n- Nhất quán · Hai nơi khác?\n- Kịp thời · Dữ liệu cũ?\n- Hợp lệ · Sai định dạng?\n- Chính xác · Sai thực tế?\nLưới sáu chiều giúp người học phân loại lỗi trước khi tính tỷ lệ.\n\n### Tự kiểm tra\nChỉ ra hai chiều quan trọng nhất trong ca này.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S02","title":"Phòng ngừa trước, phát hiện sau","content":"Quy tắc ở điểm nhập có thể chặn giá trị ngoài phạm vi; báo cáo ngoại lệ tìm lỗi đã đi vào hệ thống. Mỗi kiểm soát cần công thức đo, ngưỡng, người phụ trách và tần suất kiểm tra. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Hai lớp kiểm soát\n- Phòng ngừa · Ràng buộc lúc nhập\n- Phát hiện · Báo cáo ngoại lệ\n- Xử lý · Giao người sửa\nSơ đồ đi từ ngăn lỗi mới tới phát hiện lỗi cũ và giao xử lý.\n\n### Tự kiểm tra\nViết một quy tắc phòng ngừa và một quy tắc phát hiện.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S03","title":"Không che giấu dữ liệu yếu","content":"Bảng điểm nêu số bản ghi kiểm tra, số lỗi, tỷ lệ và ảnh hưởng tới quyết định. Phân biệt dữ liệu sai với giá trị bất thường cần điều tra. Nếu chất lượng chưa đạt ngưỡng, nêu rõ khuyến nghị tạm thời.\n\n### Bảng điểm có mẫu số\n- Mẫu kiểm · 100 giao dịch\n- Thiếu mã · 2 giao dịch\n- Tỷ lệ đủ · 98%\nBa ô số chỉ rõ mẫu số 100, hai lỗi thiếu mã và tỷ lệ đủ 98%.\n\n### Tự kiểm tra\nGhi quyết định có thể hoặc chưa thể đưa ra.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S04","title":"Mỗi chiều phải có phép đo","content":"Ví dụ độ đầy đủ mã chứng từ bằng số giao dịch có mã chia tổng giao dịch cần mã. Tính duy nhất đo số mã không trùng; tính kịp thời so thời điểm cập nhật với hạn dùng. Ghi rõ mẫu số và ngoại lệ hợp lệ; một tỷ lệ không có mẫu số không đủ để ra quyết định.\n\n### Công thức độ đầy đủ\n- Có mã · 98 giao dịch\n- Cần mã · 100 giao dịch\n- Tỷ lệ · 98 / 100 = 98%\nBa ô số giả lập thể hiện tử số, mẫu số và tỷ lệ đầy đủ mã chứng từ.\n\n### Tự kiểm tra\nViết công thức và mẫu số cho một chiều.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S05","title":"Hợp lệ chưa chắc chính xác","content":"Một email đúng cấu trúc có thể thuộc sai khách hàng: hợp lệ về định dạng nhưng sai thực tế. Một giao dịch giá trị lớn có thể là bất thường nhưng chưa chắc sai. Hãy kiểm tra bằng nguồn gốc và quy trình thay vì tự xóa những dòng khác thường.\n\n### Hai loại kiểm tra\n- Hợp lệ · Đúng định dạng/quy tắc\n- Chính xác · Đúng sự thật theo nguồn gốc\n- Bất thường · Cần điều tra, chưa phải lỗi\nBa thẻ phân biệt kiểm tra định dạng, đối chiếu thực tế và tín hiệu bất thường.\n\n### Tự kiểm tra\nNêu một trường hợp hợp lệ nhưng sai thực tế.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S06","title":"Chặn lỗi mới, tìm lỗi cũ","content":"Kiểm soát phòng ngừa ở điểm nhập có thể buộc mã nguồn hoặc kiểm tra định dạng; kiểm soát phát hiện chạy báo cáo thiếu/trùng sau nhập. Với mỗi quy tắc phải có người nhận ngoại lệ, hạn xử lý và bằng chứng đã sửa. Nếu chỉ tạo cảnh báo mà không giao xử lý, chất lượng không cải thiện.\n\n### Vòng kiểm soát\n- Nhập · Kiểm tra bắt buộc\n- Sau nhập · Báo cáo ngoại lệ\n- Sửa · Giao người · ghi dấu\nSơ đồ ba bước cho thấy kiểm soát phòng ngừa và phát hiện cần bước xử lý cuối.\n\n### Tự kiểm tra\nViết một quy tắc phòng ngừa và một quy tắc phát hiện.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S07","title":"Ưu tiên lỗi ảnh hưởng quyết định","content":"Kế toán ưu tiên mã chứng từ thiếu, mã trùng và khoản chưa khớp ngân hàng; Marketing ưu tiên lead trùng, nguồn thiếu và UTM không hợp lệ. Chọn ngưỡng theo tác động đến báo cáo, không theo một con số chung cho mọi ngành. Ghi rõ khi nào phải tạm dừng kết luận. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nChọn hai lỗi cần xử lý trước và vì sao.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S08","title":"Đọc bảng điểm như một quyết định","content":"Báo cáo chất lượng phải ghi bộ dữ liệu, thời điểm đo, mẫu số, số lỗi, tỷ lệ, ngưỡng và người xử lý. Nêu tác động: liệu còn đủ tin cậy để duyệt ngân sách hay chốt báo cáo không? Một bảng toàn màu xanh nhưng không có phép đo là hình trang trí, không phải minh chứng.\n\n### Quyết định chất lượng\n- Đạt ngưỡng · Dùng có lưu vết\n- Chưa đạt · Sửa và đo lại\n- Chưa rõ · Nêu giả định\nBa trạng thái sử dụng dữ liệu dựa trên kết quả đo, không dựa vào màu sắc đơn thuần.\n\n### Tự kiểm tra\nViết một quyết định dùng/chưa dùng dữ liệu có điều kiện.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S09","title":"Làm mẫu · Tính bảng điểm chất lượng có mẫu số","content":"Giả sử 100 giao dịch phải có mã chứng từ và 98 giao dịch có mã: độ đầy đủ là 98/100 = 98%. Một mã lặp ảnh hưởng tính duy nhất; email đúng cú pháp nhưng thuộc sai người ảnh hưởng tính chính xác. Ghi rõ mẫu số, kỳ đo, ngoại lệ hợp lệ và chủ sở hữu. Không tô ô xanh nếu chưa có phép đo; lỗi chưa giải quyết cần quyết định dùng dữ liệu có điều kiện hay tạm dừng. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S10","title":"Tự làm · Tính bảng điểm chất lượng có mẫu số","content":"Đo sáu chiều chất lượng, chọn ngưỡng và giao xử lý ngoại lệ. Thực hiện theo bốn bước: 1) Chọn tập dữ liệu, thời điểm và sáu chiều: đầy đủ, duy nhất, nhất quán, kịp thời, hợp lệ, chính xác. 2) Viết tử số, mẫu số/ngưỡng và ít nhất sáu quy tắc kiểm tra có thể áp dụng; phân loại phòng ngừa hoặc phát hiện. 3) Phân loại một bất thường chưa xác minh và một lỗi đã xác nhận. 4) Giao người xử lý, hạn đo lại và quyết định dùng hoặc tạm dừng dữ liệu. Sản phẩm cần tạo: Bảng điểm sáu chiều, ít nhất sáu quy tắc kiểm tra, danh sách ngoại lệ và kế hoạch kiểm soát.\n\n### Bốn bước thực hành\n- 01 · Chọn tập dữ liệu, thời điểm và sáu chiều: đầy đủ, duy nhất, nhất quán, kịp thời, hợp lệ, chính xác.\n- 02 · Viết tử số, mẫu số/ngưỡng và ít nhất sáu quy tắc kiểm tra có thể áp dụng; phân loại phòng ngừa hoặc phát hiện.\n- 03 · Phân loại một bất thường chưa xác minh và một lỗi đã xác nhận.\n- 04 · Giao người xử lý, hạn đo lại và quyết định dùng hoặc tạm dừng dữ liệu.\nQuy trình thực hành tính bảng điểm chất lượng có mẫu số có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M02/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Tỷ lệ có cả tử số, mẫu số và kỳ. Hợp lệ định dạng không bị nhầm với chính xác thực tế. Mỗi ngoại lệ ưu tiên có người xử lý và hạn kiểm tra lại. Lỗi thường gặp: Xóa dòng bất thường để bảng đẹp hơn mà không điều tra và lưu dấu vết. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Tỷ lệ có cả tử số, mẫu số và kỳ.\n- Tiêu chí 2 · Hợp lệ định dạng không bị nhầm với chính xác thực tế.\n- Tiêu chí 3 · Mỗi ngoại lệ ưu tiên có người xử lý và hạn kiểm tra lại.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"}],"questions":[{"code":"M1-A/M02/GENERAL/Q01","text":"Email đúng định dạng nhưng thuộc sai khách hàng vi phạm chiều nào?","explanation":"Định dạng có thể hợp lệ nhưng thông tin không phản ánh đúng thực tế.","options":["Tính hợp lệ","Tính chính xác","Tính đầy đủ"],"correctIndex":1},{"code":"M1-A/M02/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-A/M02/GENERAL/Q03","text":"Có 98/100 giao dịch đủ mã bắt buộc. Độ đầy đủ là?","explanation":"Tử số là 98 dòng đủ mã, mẫu số là 100 dòng cần mã.","options":["98%","2%","100%"],"correctIndex":0},{"code":"M1-A/M02/GENERAL/Q04","text":"Một email đúng định dạng nhưng gắn sai người. Điều gì chưa đạt?","explanation":"Đúng cấu trúc không bảo đảm đúng đối tượng.","options":["Tính hợp lệ định dạng","Tính chính xác so với thực tế","Tính kịp thời"],"correctIndex":1},{"code":"M1-A/M02/GENERAL/Q05","text":"Một cảnh báo lỗi được tạo nhưng không ai xử lý. Cần bổ sung gì?","explanation":"Kiểm soát phát hiện chỉ hữu ích khi có luồng xử lý ngoại lệ.","options":["Chỉ đổi màu cảnh báo","Chủ sở hữu, hạn xử lý và dấu vết sửa/đo lại","Xóa cảnh báo"],"correctIndex":1}]},{"title":"Quản trị dữ liệu và vòng đời thông tin","description":"Thống nhất định nghĩa, nguồn chính thức, vai trò và vòng đời dữ liệu.","purpose":{"title":"Tạo từ điển chỉ số và kiểm soát thay đổi","goal":"Định nghĩa một chỉ số để phòng ban khác tính lại được và biết ai chịu trách nhiệm.","example":"“Lead đủ điều kiện” không thể chỉ là tên cột; cần điều kiện đủ chuẩn, cách loại trùng, trạng thái, kỳ, nguồn chính thức và chủ sở hữu. Tương tự, “doanh thu” phải nêu xử lý hóa đơn hủy/điều chỉnh. Nếu thay điều kiện, ghi đề xuất, tác động tới số cũ, người duyệt, ngày hiệu lực và phiên bản. Truy cập dữ liệu nhạy cảm theo quyền phù hợp, không tự đặt một thời hạn lưu chung cho mọi tổ chức.","steps":["Chọn một chỉ số có tranh cãi giữa hai phòng ban.","Tạo từ điển ít nhất mười trường, mỗi trường có định nghĩa, kiểu/giá trị hợp lệ, nguồn, mức nhạy cảm và chủ sở hữu.","Gán chủ sở hữu, người quản lý chất lượng và người vận hành; xác định nguồn chính thức.","Mô phỏng thay đổi v1→v2 và lập lịch lưu/hủy cho ba loại dữ liệu theo chính sách áp dụng."],"output":"Từ điển tối thiểu 10 trường, ma trận ba vai trò, định nghĩa chỉ số thống nhất và lịch lưu/hủy cho ba loại dữ liệu.","checks":["Một người ngoài nhóm có thể tính lại chỉ số từ định nghĩa.","Nguồn chính thức và quyền truy cập rõ ràng.","Thay đổi định nghĩa không bị nhầm với tăng/giảm thực tế."],"mistake":"Sửa công thức trong dashboard nhưng không cập nhật từ điển và lịch sử.","minutes":65,"role":"Vị trí khác","situation":"Áp dụng vào một quyết định thực tế của vị trí.","contextual":["Áp dụng vào một quyết định thực tế của vị trí.","Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."],"modulePrompt":"Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra."},"minutes":65,"slides":[{"code":"M1-A/M03/S01","title":"Một chỉ số cần một cách hiểu","content":"Từ điển dữ liệu ghi tên trường, ý nghĩa, kiểu, giá trị hợp lệ, đơn vị, kỳ, nguồn và chủ sở hữu. Khi hai phòng báo số khác nhau, trước hết kiểm tra định nghĩa và nguồn chính thức; không sửa số bằng cách lấy trung bình.\n\n### Một mục từ điển dữ liệu\n- Tên · Doanh thu thuần\n- Định nghĩa · Sau điều chỉnh hợp lệ\n- Nguồn · Sổ cái đã chốt\nPhiếu từ điển dữ liệu làm rõ tên, định nghĩa và nguồn chính thức của chỉ số.\n\n### Tự kiểm tra\nViết định nghĩa cho một chỉ số hay tranh cãi.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S02","title":"Ai quyết, ai giữ chất lượng?","content":"Chủ sở hữu dữ liệu chịu trách nhiệm cuối cùng; người quản lý dữ liệu theo dõi định nghĩa và chất lượng hằng ngày; người sử dụng tuân thủ quy tắc. Ghi quyền phê duyệt thay đổi, nơi lưu nguồn chính thức và đường dẫn truy vết. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Ba vai trò\n- 01 · Chủ sở hữu · Phê duyệt định nghĩa\n- 02 · Người quản lý · Theo dõi chất lượng\n- 03 · Người dùng · Áp dụng đúng quy tắc\nBa vai trò tách quyền phê duyệt, vận hành chất lượng và sử dụng dữ liệu.\n\n### Tự kiểm tra\nGán ba vai trò cho một bộ dữ liệu.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S03","title":"Giữ dữ liệu đúng thời hạn và mục đích","content":"Quy trình phải nói rõ tạo, kiểm tra, chia sẻ, lưu, lưu trữ và hủy dữ liệu. Thời hạn giữ cần được đối chiếu quy định và nhu cầu nghiệp vụ tại nơi triển khai; bản demo không tự đặt thời hạn pháp lý.\n\n### Vòng đời dữ liệu\n- Tạo · Ghi nguồn\n- Dùng · Kiểm tra · chia sẻ\n- Lưu · Bảo quản theo quy định\n- Hủy · Theo chính sách áp dụng\nTrục vòng đời đi từ tạo đến hủy; không ngụ ý một thời hạn lưu giữ chung cho mọi dữ liệu.\n\n### Tự kiểm tra\nViết một điểm kiểm soát khi kết thúc vòng đời.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S04","title":"Định nghĩa chỉ số đủ để người khác tính lại","content":"Một mục từ điển có tên, định nghĩa, công thức, tử số, mẫu số, đơn vị, kỳ, nguồn chính thức, chủ sở hữu và lịch sử thay đổi. Ví dụ “lead đủ điều kiện” cần điều kiện loại trùng và trạng thái xử lý; “doanh thu” cần cách xử lý hóa đơn hủy.\n\n### Mục từ điển tối thiểu\n- Tên · Chỉ số nghiệp vụ\n- Cách tính · Tử số / mẫu số\n- Nguồn · Hệ thống đã chốt\n- Chủ sở hữu · Người phê duyệt\nPhiếu từ điển kết nối tên chỉ số với phép tính, nguồn và trách nhiệm.\n\n### Tự kiểm tra\nViết định nghĩa và nguồn chính thức cho một chỉ số.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S05","title":"Phân vai để lỗi có người giải quyết","content":"Chủ sở hữu phê duyệt định nghĩa và mức chất lượng; người quản lý dữ liệu theo dõi lỗi và điều phối sửa; người vận hành tạo hoặc cập nhật bản ghi; người dùng báo sai lệch. Ghi ai có quyền đổi định nghĩa vì một thay đổi nhỏ có thể làm đứt chuỗi báo cáo.\n\n### Chuỗi trách nhiệm\n- 01 · Chủ sở hữu · Phê duyệt chuẩn\n- 02 · Người quản lý · Theo dõi ngoại lệ\n- 03 · Người vận hành · Sửa có dấu vết\nBa vai trò tách quyết định chuẩn, theo dõi chất lượng và cập nhật dữ liệu.\n\n### Tự kiểm tra\nGán người phê duyệt và người xử lý lỗi khác nhau.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S06","title":"Phiên bản hóa định nghĩa, không sửa âm thầm","content":"Khi đổi cách tính, ghi đề xuất, tác động tới báo cáo cũ, người duyệt, ngày hiệu lực và phiên bản mới. Giữ khả năng giải thích vì sao số tháng trước khác sau thay đổi. Không ghi đè từ điển mà không có lịch sử; người đọc có thể hiểu nhầm sự thay đổi là tăng trưởng thật.\n\n### Thay đổi có kiểm soát\n- v1 · Định nghĩa cũ\n- Duyệt · Tác động và người duyệt\n- v2 · Ngày hiệu lực rõ\nTrục phiên bản cho thấy định nghĩa mới cần phê duyệt và ngày áp dụng.\n\n### Tự kiểm tra\nNêu ba thông tin bắt buộc trong nhật ký thay đổi.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S07","title":"Thiết kế chuẩn cho bộ dữ liệu đang dùng","content":"Với Kế toán, xác định nguồn chính thức của doanh thu, trạng thái hóa đơn và người xử lý đối chiếu; với Marketing, xác định lead đủ điều kiện, nguồn chiến dịch và người quản trị UTM. Quyền truy cập phải phù hợp mức nhạy cảm, nhất là thông tin khách hàng và tài chính. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện của Vị trí khác\n- Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n- Nguồn · Ghi tài liệu gốc và kỳ dữ liệu\n- Sản phẩm · Có thể kiểm tra lại\nBảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.\n\n### Tự kiểm tra\nGhi một quy tắc truy cập và một quy tắc chất lượng.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S08","title":"Kiểm tra toàn vòng đời","content":"Mô tả cách dữ liệu được tạo, xác minh, chia sẻ, lưu, lưu trữ và hủy theo chính sách áp dụng. Không đặt một thời hạn lưu chung trong bài học vì yêu cầu pháp lý và nghiệp vụ có thể khác. Bản cuối phải cho thấy cách duy trì chất lượng sau khi dự án phân tích kết thúc.\n\n### Vòng đời có điểm kiểm soát\n- Tạo · Mã · nguồn\n- Dùng · Quyền · chất lượng\n- Lưu · Theo chính sách\n- Hủy · Có phê duyệt\nTrục vòng đời chỉ vị trí cần kiểm soát, không tự quy định số năm lưu giữ.\n\n### Tự kiểm tra\nNêu điểm kiểm soát ở lúc tạo và lúc kết thúc vòng đời.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S09","title":"Làm mẫu · Tạo từ điển chỉ số và kiểm soát thay đổi","content":"“Lead đủ điều kiện” không thể chỉ là tên cột; cần điều kiện đủ chuẩn, cách loại trùng, trạng thái, kỳ, nguồn chính thức và chủ sở hữu. Tương tự, “doanh thu” phải nêu xử lý hóa đơn hủy/điều chỉnh. Nếu thay điều kiện, ghi đề xuất, tác động tới số cũ, người duyệt, ngày hiệu lực và phiên bản. Truy cập dữ liệu nhạy cảm theo quyền phù hợp, không tự đặt một thời hạn lưu chung cho mọi tổ chức. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\n\n### Dữ kiện để làm mẫu\n- Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.\n- Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.\nDữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.\n\n### Tự kiểm tra\nĐánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S10","title":"Tự làm · Tạo từ điển chỉ số và kiểm soát thay đổi","content":"Định nghĩa một chỉ số để phòng ban khác tính lại được và biết ai chịu trách nhiệm. Thực hiện theo bốn bước: 1) Chọn một chỉ số có tranh cãi giữa hai phòng ban. 2) Tạo từ điển ít nhất mười trường, mỗi trường có định nghĩa, kiểu/giá trị hợp lệ, nguồn, mức nhạy cảm và chủ sở hữu. 3) Gán chủ sở hữu, người quản lý chất lượng và người vận hành; xác định nguồn chính thức. 4) Mô phỏng thay đổi v1→v2 và lập lịch lưu/hủy cho ba loại dữ liệu theo chính sách áp dụng. Sản phẩm cần tạo: Từ điển tối thiểu 10 trường, ma trận ba vai trò, định nghĩa chỉ số thống nhất và lịch lưu/hủy cho ba loại dữ liệu.\n\n### Bốn bước thực hành\n- 01 · Chọn một chỉ số có tranh cãi giữa hai phòng ban.\n- 02 · Tạo từ điển ít nhất mười trường, mỗi trường có định nghĩa, kiểu/giá trị hợp lệ, nguồn, mức nhạy cảm và chủ sở hữu.\n- 03 · Gán chủ sở hữu, người quản lý chất lượng và người vận hành; xác định nguồn chính thức.\n- 04 · Mô phỏng thay đổi v1→v2 và lập lịch lưu/hủy cho ba loại dữ liệu theo chính sách áp dụng.\nQuy trình thực hành tạo từ điển chỉ số và kiểm soát thay đổi có sản phẩm kiểm tra được.\n\n### Tự kiểm tra\nTạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"},{"code":"M1-A/M03/S11","title":"So sản phẩm với tiêu chí","content":"Sản phẩm cần đạt ba dấu hiệu: Một người ngoài nhóm có thể tính lại chỉ số từ định nghĩa. Nguồn chính thức và quyền truy cập rõ ràng. Thay đổi định nghĩa không bị nhầm với tăng/giảm thực tế. Lỗi thường gặp: Sửa công thức trong dashboard nhưng không cập nhật từ điển và lịch sử. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.\n\n### Phiếu tự kiểm\n- Tiêu chí 1 · Một người ngoài nhóm có thể tính lại chỉ số từ định nghĩa.\n- Tiêu chí 2 · Nguồn chính thức và quyền truy cập rõ ràng.\n- Tiêu chí 3 · Thay đổi định nghĩa không bị nhầm với tăng/giảm thực tế.\nBa tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.\n\n### Tự kiểm tra\nĐánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.\n\n### Nguồn tham khảo\nChính phủ Anh · Khung chất lượng dữ liệu\nhttps://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework"}],"questions":[{"code":"M1-A/M03/GENERAL/Q01","text":"Hai phòng ban báo một chỉ số khác nhau vì định nghĩa khác. Cần làm gì trước?","explanation":"Quản trị giải quyết khác biệt định nghĩa trước khi xử lý phép tính.","options":["Lấy trung bình hai số","Chọn số cao hơn","Thống nhất định nghĩa và nguồn chính thức trong từ điển dữ liệu"],"correctIndex":2},{"code":"M1-A/M03/GENERAL/Q02","text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":["Một kết luận không ghi nguồn","Nguồn, cách làm và kết luận có giới hạn","Chỉ một ảnh chụp"],"correctIndex":1},{"code":"M1-A/M03/GENERAL/Q03","text":"Mục từ điển cho chỉ số cần tối thiểu gì?","explanation":"Người khác phải tính lại được và biết ai chịu trách nhiệm.","options":["Tên và màu biểu đồ","Định nghĩa, công thức, kỳ, nguồn chính thức, chủ sở hữu","Chỉ tên người nhập dữ liệu"],"correctIndex":1},{"code":"M1-A/M03/GENERAL/Q04","text":"Đổi công thức tính chỉ số. Hành động nào có kiểm soát?","explanation":"Lịch sử thay đổi giúp phân biệt thay đổi định nghĩa với thay đổi thực tế.","options":["Ghi đè mà không thông báo","Ghi tác động, người duyệt, ngày hiệu lực và phiên bản mới","Chỉ sửa ảnh biểu đồ"],"correctIndex":1},{"code":"M1-A/M03/GENERAL/Q05","text":"Dữ liệu hết thời hạn sử dụng. Cách xử lý đúng?","explanation":"Vòng đời dữ liệu cần tuân thủ chính sách cụ thể của tổ chức và quy định áp dụng.","options":["Giữ mãi mọi bản sao","Theo chính sách áp dụng, xác định người phê duyệt và lưu dấu vết xử lý","Xóa tùy ý không ghi nhận"],"correctIndex":1}]}],"assignments":{"general":{"title":"Bài cuối khóa M1-A · vị trí của bạn","situation":"Áp dụng vào một quyết định thực tế của vị trí.","prompt":"Nêu nhu cầu, nguồn, cách kiểm tra, sản phẩm công việc và kết luận có giới hạn.","deliverables":["Nhật ký nguồn và định nghĩa","Sản phẩm công việc có thể kiểm tra","Giới hạn và đề xuất tiếp theo"],"caseFacts":[],"rubric":[["Kế hoạch và thực hiện nghiên cứu đa nguồn",25],["Đánh giá chất lượng định lượng sáu chiều",25],["Bộ tài liệu quản trị hoàn chỉnh",25],["Báo cáo có khuyến nghị và giới hạn",25]],"pass":70,"minimumCriterion":50,"requirements":["Lập kế hoạch nghiên cứu 4 bước, phối hợp nguồn nội bộ và bên ngoài, ghi khoảng trống và giả định.","Chấm sáu chiều chất lượng bằng phép đo có tử số, mẫu số/ngưỡng; viết ít nhất 6 quy tắc kiểm tra và phân loại phòng ngừa hoặc phát hiện.","Tạo từ điển tối thiểu 10 trường, phân vai chủ sở hữu, người quản lý dữ liệu và người vận hành; xác định nguồn chính thức.","Lập lịch lưu trữ và hủy cho 3 loại dữ liệu theo chính sách áp dụng; viết khuyến nghị, độ tin cậy và giới hạn."]},"accounting":{"title":"Bài cuối khóa M1-A · Kế toán","situation":"Ban giám đốc nghi ngờ chất lượng dữ liệu chi phí và doanh thu từ ba hệ thống.","prompt":"Xây hồ sơ chất lượng và quản trị dữ liệu doanh thu giả lập cho ban giám đốc, dùng ít nhất ba hệ thống nguồn.","deliverables":["Kế hoạch nghiên cứu và các khoảng trống","Bảng điểm sáu chiều có mẫu số/ngưỡng","Từ điển dữ liệu, phân vai và khuyến nghị có điều kiện"],"caseFacts":["Sổ cái: 100 giao dịch · 2 giao dịch thiếu mã chứng từ · tổng 290.000.000 đ","Hóa đơn: 101 dòng · 1 mã lặp · 1 hóa đơn hủy chưa gắn trạng thái vào bảng xuất","Ngân hàng: 96 giao dịch khớp mã, 4 giao dịch cần đố